import {randomBytes,createHash} from 'node:crypto';
import {Ebay} from '../src/ebay.js';
import {Gmail} from '../src/gmail.js';
import {ReviewRun} from '../src/review-run.js';
import {CLIENT_ID,SENDER,EBAY_SCOPES,GOOGLE_SCOPES} from '../src/config.js';
import {safeError} from '../src/engine.js';
import {loadOlder,prepareOlder} from './manual-review.js';
export const actions=new Set(['older-list','older-review','verify','cutoff','message-access','dry-run','ebay-client','google-client','ebay-authorize','ebay-complete','google-authorize']);
export async function action(name,input,ctx,cfg,sessionId) {
 const {store:s,state,vault}=ctx,e=new Ebay(vault),g=new Gmail(vault),r=new ReviewRun({store:s,ebay:e});
 if(!actions.has(name))throw new Error('Action unavailable in review mode.');
 const invalidate=()=>{s.set('checks',{ok:false});s.set('messageAccess',null);};
 const newState=provider=>{for(const [key,v]of Object.entries(state.oauth))if(Date.now()-v.created>600000)delete state.oauth[key];const key=randomBytes(32).toString('hex');state.oauth[key]={provider,created:Date.now(),sessionId};return key;};
 if(name==='ebay-client'){if(input.clientId!==CLIENT_ID||typeof input.secret!=='string'||!input.secret||/\s|•/.test(input.secret))throw new Error('Only the test 2 client and complete Cert ID are allowed.');vault.update({ebayClientId:CLIENT_ID,ebaySecret:input.secret});invalidate();return {ok:true};}
 if(name==='google-client'){const web=input.client?.web;if(!web?.client_id?.endsWith('.apps.googleusercontent.com')||!web.client_secret||!web.redirect_uris?.includes(cfg.origin+'/api/google-callback'))throw new Error('Upload a Google Web application client JSON with this site’s /api/google-callback redirect URI.');vault.update({googleClientId:web.client_id,googleClientSecret:web.client_secret,googleRefreshToken:null});invalidate();return {ok:true};}
 if(name==='google-authorize'){const secrets=vault.load();if(!secrets.googleClientId)throw new Error('Save a Google Web client first.');const key=newState('google'),verifier=randomBytes(48).toString('base64url');state.oauth[key].verifier=verifier;return {url:'https://accounts.google.com/o/oauth2/v2/auth?'+new URLSearchParams({client_id:secrets.googleClientId,redirect_uri:cfg.origin+'/api/google-callback',response_type:'code',scope:GOOGLE_SCOPES.join(' '),access_type:'offline',prompt:'consent',login_hint:SENDER,state:key,code_challenge:createHash('sha256').update(verifier).digest('base64url'),code_challenge_method:'S256'})};}
 if(name==='ebay-authorize'){if(!vault.status().ebayClient)throw new Error('Save test 2 credentials first.');if(!/^test-test-test2-PRD--[\w-]+$/.test(input.runame))throw new Error('Only a test 2 redirect name is allowed.');const key=newState('ebay');state.oauth[key].runame=input.runame;return {url:'https://auth.ebay.com/oauth2/authorize?'+new URLSearchParams({client_id:CLIENT_ID,response_type:'code',redirect_uri:input.runame,scope:EBAY_SCOPES.join(' '),state:key})};}
 if(name==='ebay-complete'){const u=new URL(input.callback);if(u.protocol!=='https:'||!['auth.ebay.com','auth2.ebay.com'].includes(u.hostname))throw new Error('Use the eBay authorization result URL.');const key=u.searchParams.get('state'),p=state.oauth[key];delete state.oauth[key];if(!p||p.provider!=='ebay'||p.sessionId!==sessionId||Date.now()-p.created>600000||!u.searchParams.get('code'))throw new Error('Authorization expired. Start again.');await e.exchange(u.searchParams.get('code'),p.runame);invalidate();return {ok:true};}
 if(name==='verify'){
 const c={at:new Date().toISOString(),ok:false,ebay:false,gmail:false,orders:false,listing:false};s.set('messageAccess',null);
 try{await e.token(true);const seller=await e.identity(),prior=s.get('seller');if(seller.toLowerCase()!=='virventures'||(prior&&prior.toLowerCase()!==seller.toLowerCase()))throw new Error('Seller must be virventures.');s.set('seller',seller);c.ebay=true;c.seller=seller;const end=new Date().toISOString();await e.orders(new Date(Date.now()-86400000).toISOString(),end);c.orders=true;const item=input.itemId||s.get('testItemId');if(!/^\d+$/.test(item||''))throw new Error('Enter a current listing ID.');const listing=await e.listing(item);if(listing.seller.toLowerCase()!==seller.toLowerCase())throw new Error('Listing seller mismatch.');c.listing=true;s.set('testItemId',item);}catch(err){c.ebayError=safeError(err);}
 try{await g.token(true);await g.profile();c.gmail=true;}catch(err){c.gmailError=safeError(err);}c.ok=c.ebay&&c.gmail&&c.orders&&c.listing;s.set('checks',c);return c;
 }
 if(name==='older-list')return loadOlder(input,ctx,e,sessionId);
 if(name==='older-review')return prepareOlder(input,ctx,e,sessionId);
 r.requireChecks();if(name==='cutoff')return r.arm();if(name==='message-access')return r.checkAccess();if(name==='dry-run')return r.run();
}

