import {randomBytes,createHmac,createHash,timingSafeEqual,createCipheriv,createDecipheriv} from 'node:crypto';
export const equal=(a,b)=>typeof a==='string'&&typeof b==='string'&&a.length<=4096&&b.length<=4096&&timingSafeEqual(createHash('sha256').update(a).digest(),createHash('sha256').update(b).digest());
export function configuration(env=process.env) {
 const origin=new URL(env.REPLYASSIST_ORIGIN || env.URL || 'https://unconfigured.invalid').origin;
 if(!origin.startsWith('https://') || origin==='https://unconfigured.invalid' || !/^[a-f0-9]{64}$/i.test(env.REPLYASSIST_ENCRYPTION_KEY||'') || (env.REPLYASSIST_ADMIN_PASSWORD||'').length<24) throw new Error('Cloud setup incomplete. Configure the origin, encryption key and a password of at least 24 characters in Netlify.');
 return {origin,key:Buffer.from(env.REPLYASSIST_ENCRYPTION_KEY,'hex'),password:env.REPLYASSIST_ADMIN_PASSWORD};
}
export const mac=(value,cfg)=>createHmac('sha256',cfg.key).update(value).digest('base64url');
export function session(cfg,now=Date.now()) {const payload=Buffer.from(JSON.stringify({exp:now+8*3600000,id:randomBytes(24).toString('hex')})).toString('base64url');return payload+'.'+mac('session:'+payload+':'+createHash('sha256').update(cfg.password).digest('hex'),cfg);}
export function authenticate(req,cfg,now=Date.now()) {
 const token=(req.headers.get('cookie')||'').split(';').map(s=>s.trim()).find(s=>s.startsWith('__Host-replyassist='))?.slice(19);
 if(!token||token.length>1024)throw new Error('Sign in to ReplyAssist.');
 const [p,sig,...rest]=token.split('.');
 if(rest.length||!equal(sig,mac('session:'+p+':'+createHash('sha256').update(cfg.password).digest('hex'),cfg)))throw new Error('Sign in to ReplyAssist.');
 const data=JSON.parse(Buffer.from(p,'base64url').toString());if(!Number.isFinite(data.exp)||data.exp<=now||data.exp>now+8*3600000)throw new Error('Session expired.');
 return {csrf:mac('csrf:'+token,cfg),id:data.id};
}
export function requirePost(req,cfg,auth) {if(req.method!=='POST'||req.headers.get('origin')!==cfg.origin||req.headers.get('content-type')?.split(';')[0]!=='application/json'||(auth&&!equal(req.headers.get('x-csrf'),auth.csrf)))throw new Error('Invalid request origin or CSRF token.');}
export async function body(req) {const reader=req.body?.getReader();if(!reader)return {};let size=0,parts=[];for(;;){const {value,done}=await reader.read();if(done)break;size+=value.length;if(size>100000){await reader.cancel();throw new Error('Request too large.');}parts.push(Buffer.from(value));}return JSON.parse(Buffer.concat(parts).toString()||'{}');}
export function seal(value,cfg) {const iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',cfg.key,iv);const bytes=Buffer.concat([cipher.update(JSON.stringify(value)),cipher.final()]);return [iv,cipher.getAuthTag(),bytes].map(b=>b.toString('base64')).join('.');}
export function unseal(value,cfg) {const [iv,tag,bytes]=value.split('.').map(s=>Buffer.from(s,'base64'));const cipher=createDecipheriv('aes-256-gcm',cfg.key,iv);cipher.setAuthTag(tag);return JSON.parse(Buffer.concat([cipher.update(bytes),cipher.final()]).toString());}

