import pg from 'pg';
import {getConnectionString} from '@netlify/database';
import {Store} from '../src/store.js';
import {seal,unseal} from './security.js';
const tables={settings:['key','value'],jobs:['key','seller','conversation','message','created','payload'],issues:['key','payload'],events:['id','at','kind','detail'],orders:['id','buyer','items','created'],review_proposals:['key','seller','conversation','payload']};
export function restore(snapshot={}) {const store=new Store(':memory:');for(const [table,columns] of Object.entries(tables))for(const row of snapshot[table]||[])store.db.prepare(`INSERT INTO ${table} (${columns.join(',')}) VALUES (${columns.map(()=>'?').join(',')})`).run(...columns.map(k=>row[k]));return store;}
export function snapshot(store) {return Object.fromEntries(Object.keys(tables).map(t=>[t,store.db.prepare(`SELECT * FROM ${t}`).all()]));}
export class CloudVault {
 constructor(state){this.state=state;}
 load(){return {...this.state.secrets};}
 update(patch){Object.assign(this.state.secrets,patch);}
 status(){const s=this.load();return {ebayClient:!!s.ebaySecret,ebaySeller:!!s.ebayRefreshToken,googleClient:!!s.googleClientId,gmail:!!s.googleRefreshToken};}
}
export async function transaction(cfg,fn,{readOnly=false}={}) {
 const client=new pg.Client({connectionString:getConnectionString(),connectionTimeoutMillis:8000,query_timeout:15000});let store;
 await client.connect();
 try {await client.query(readOnly?'BEGIN READ ONLY':'BEGIN');await client.query("SET LOCAL lock_timeout = '2s'");await client.query("SET LOCAL idle_in_transaction_session_timeout = '300s'");const {rows}=await client.query('SELECT payload FROM replyassist_cloud_state WHERE id=1'+(readOnly?'':' FOR UPDATE'));if(!rows.length)throw new Error('Cloud database migration missing.');
 const state=rows[0].payload?unseal(rows[0].payload,cfg):{secrets:{},oauth:{},tasks:{},snapshot:{}};store=restore(state.snapshot);const result=await fn({state,store,vault:new CloudVault(state)});if(!readOnly){state.snapshot=snapshot(store);await client.query('UPDATE replyassist_cloud_state SET payload=$1,updated_at=now() WHERE id=1',[seal(state,cfg)]);}await client.query('COMMIT');return result;
 }catch(e){await client.query('ROLLBACK').catch(()=>{});throw e;}finally{store?.close();await client.end();}
}

