import {configuration,equal,body,mac} from '../../cloud/security.js';
import {transaction} from '../../cloud/state.js';
import {action} from '../../cloud/actions.js';
import {ManualReviewError} from '../../cloud/manual-review.js';
import {withRequestBudget} from '../../src/http.js';
export default async function handler(req) {
