    const s=this.vault.load();
    if (!s.ebaySecret || !s.ebayRefreshToken) throw new Error('Authorize the test 2 seller account first.');
    if (s.ebayClientId!==CLIENT_ID) throw new Error('Only the pinned test 2 keyset is allowed.');
