  }
  async exchange(code,runame) {
    const s=this.vault.load();
    if (!s.ebaySecret || s.ebayClientId!==CLIENT_ID) throw new Error('Save the test 2 client credential first.');
    const d=await request('https://api.ebay.com/identity/v1/oauth2/token',{method:'POST',headers:{Authorization:'Basic '+Buffer.from(`${CLIENT_ID}:${s.ebaySecret}`).toString('base64'),'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({grant_type:'authorization_code',code,redirect_uri:runame})});
    if (!d.refresh_token) throw new Error('No eBay refresh token returned.');
    this.vault.update({ebayRefreshToken:d.refresh_token,ebayClientId:CLIENT_ID}); this.invalidate();
  }
}

