import {blockReviewOperation} from './review-lock.js';
import {decide,fingerprint,latestCustomer,inOfficeWindow} from './policy.js';
import {HOLDING,POST_ORDER} from './config.js';
const now = () => new Date().toISOString();
const same = (a,b) => a.toLowerCase()===b.toLowerCase();
const ambiguous = e => !e.status || e.status>=500 || e.status===408;
export class Engine {
  constructor({store,ebay,gmail,canSend=()=>true}) { this.store=store; this.ebay=ebay; this.gmail=gmail; this.canSend=canSend; this.busy=false; }
  async process(summary,{seller,activationAt,live,orderLookupOk}) {
    blockReviewOperation();
    const s=this.store;
    let c=await this.ebay.conversation(summary);
    const m=latestCustomer(c,seller);
    if (!m || Date.parse(m.receivedAt)<Date.parse(activationAt)) return;
    const key=`${seller.toLowerCase()}:${m.id}`;
    const existing=s.job(key);
    if (existing && existing.replyState!=='planned') return;
    let listing=null;
    if(c.itemId) { try { listing=await this.ebay.listing(c.itemId); if (!same(listing.seller,seller)) listing=null; } catch { /* Missing listing evidence always routes to review. */ } }
    const decision=decide({conversation:c,listing,message:m,matchedOrder:s.orderMatch(m.sender,c.itemId),orderLookupOk});
    const issue=s.issue(seller,c.id);
    const unresolved=issue && !issue.resolved;
    // Also catch a holding reply made by another instance/staff before we had a ledger.
    const previousHolding=c.messages.some(x=>same(x.sender,seller) && x.text===HOLDING);
    const suppress=decision.kind!=='supported_answer' && (unresolved || (previousHolding && !issue?.resolved));
    const job={key,seller,conversation:c.id,message:m.id,itemId:c.itemId,receivedAt:m.receivedAt,question:m.text,decision,summary,conversationHash:fingerprint(c),replyState:suppress?'suppressed':'planned',emailState:decision.to?'pending':'not_required',createdAt:now(),dryRun:!live};
    if (!live) {
      const records=s.get('dryRunRecords',[]); const dryKey=key+':'+job.conversationHash;
      s.set('dryRunRecords',[{...job,key:dryKey,replyState:suppress?'would_suppress':'would_send',emailState:decision.to?'would_email':'not_required'},...records.filter(x=>x.key!==dryKey)].slice(0,200));
      return;
    }
    if (existing) s.save(job); else if (!s.insert(job)) return;
    if (!suppress) {
      // Re-read the entire thread immediately before sending and recheck listing
      // evidence for auto-answers. The provider has no atomic compare-and-send.
      c=await this.ebay.conversation(summary);
      if (fingerprint(c)!==job.conversationHash || latestCustomer(c,seller)?.id!==m.id) {
        job.replyState='skipped_changed_conversation'; job.emailState='not_required'; s.save(job); return;
      }
      if (decision.kind==='supported_answer') {
        let fresh=null;
        try { fresh=await this.ebay.listing(c.itemId); } catch { /* Abort rather than send a stale answer. */ }
        const freshDecision=decide({conversation:c,listing:fresh?.seller && same(fresh.seller,seller)?fresh:null,message:m,matchedOrder:s.orderMatch(m.sender,c.itemId),orderLookupOk});
        if (freshDecision.text!==decision.text || freshDecision.kind!==decision.kind) {
          job.decision=freshDecision;
          job.emailState=freshDecision.to?'pending':'not_required';
          Object.assign(decision,freshDecision);
          s.save(job);
        }
        c=await this.ebay.conversation(summary);
        if (fingerprint(c)!==job.conversationHash || latestCustomer(c,seller)?.id!==m.id) {
          job.replyState='skipped_changed_conversation'; job.emailState='not_required'; s.save(job); return;
        }
      }
      // A durable intent is committed BEFORE making an external call. If the
      // process dies here, a restart reconciles; it never blindly repeats a send.
      if(!this.canSend()) { job.replyState='planned';s.save(job);return; }
      job.replyState='sending'; job.replyAttemptAt=now(); s.save(job);
      try { job.ebayMessageId=await this.ebay.send(c.id,decision.text); job.replyState='sent'; }
      catch(e) { job.replyState=ambiguous(e)?'unknown':'failed'; job.replyError=e.status?`eBay HTTP ${e.status}`:'Ambiguous send; awaiting reconciliation.'; }
