    // using the customer's receipt time, not the server's current local time.
    if (job.decision.kind==='post_order' && (!inOfficeWindow(job.receivedAt) || job.decision.to!==POST_ORDER)) {
      job.emailState='not_required'; this.store.save(job); return;
    }
