    try { for(const o of orders) s.addOrder(o); s.set('ordersSyncedAt',end); s.db.exec('COMMIT'); } catch(e) {s.db.exec('ROLLBACK');throw e;}
  }
  async poll() {
    blockReviewOperation();
    if(this.busy) return {busy:true};
    this.busy=true;
    try {
      const s=this.store, live=s.get('live',false), seller=s.get('seller');
      if(!seller) throw new Error('Verify the eBay seller connection before monitoring.');
      const cutoff=live?s.get('activationAt'):s.get('dryRunStart');
      if(!cutoff) throw new Error('Start dry monitoring or activate first.');
      if(live) {
        if(s.get('checks')?.ok!==true || Date.now()-Date.parse(s.get('checks').at)>15*60000) throw new Error('Connection verification expired; automatic sending is paused.');
        await this.reconcile();
      }
