      const start=new Date(Math.max(Date.parse(cutoff),Date.parse(cursor)-5*60000)).toISOString();
      const summaries=await this.ebay.conversations(start,end);
      let failures=0;
      for(const summary of summaries) {
        try { await this.process(summary,{seller,activationAt:cutoff,live,orderLookupOk}); }
        catch(e) {failures++;s.log('conversation_error',{conversation:summary.conversationId,error:safeError(e)});}
      }
      if(!failures) s.set(live?'cursor':'dryCursor',end);
      s.set('lastPoll',{at:end,count:summaries.length,failures,orderLookupOk,mode:live?'live':'dry_run'});
      return s.get('lastPoll');
    } finally {this.busy=false;}
  }
}
export function safeError(e) {
  if(e.status) return `Remote API returned HTTP ${e.status}.`;
  const allowed=['Review','Authorize','Verify','Only','Wrong','Gmail must','Save','Start','Connection verification','No seller','No Gmail','No eBay','Google did not','Windows','Invalid listing','Incomplete','Unexpected','Unsupported','Unsafe','Pagination','eBay listing','Listing identity','Conversation changed','Missing','Order access','Account'];
  return allowed.some(p=>e.message?.startsWith(p))?e.message:'Operation failed; inspect connection status and retry the read-only check.';
}

