import {blockReviewOperation} from './review-lock.js';
import {createHash} from 'node:crypto';
import {request} from './http.js';
import {SENDER,HUMAN,POST_ORDER} from './config.js';
export class Gmail {
  constructor(vault) { this.vault=vault; this.cached=null; }
  invalidate() { this.cached=null; }
  async token(force=false) {
    if (!force && this.cached?.until>Date.now()+60000) return this.cached.token;
    const s=this.vault.load();
    if (!s.googleClientId || !s.googleRefreshToken) throw new Error('Authorize background Gmail access first.');
    const d=await request('https://oauth2.googleapis.com/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:s.googleClientId,client_secret:s.googleClientSecret || '',refresh_token:s.googleRefreshToken,grant_type:'refresh_token'})});
    if (!d.access_token) throw new Error('No Gmail access token returned.');
    this.cached={token:d.access_token,until:Date.now()+Number(d.expires_in)*1000};
    return d.access_token;
  }
  async json(path,options={}) { if(String(options.method || 'GET').toUpperCase()!=='GET' || path.startsWith('messages')) blockReviewOperation(); return request('https://gmail.googleapis.com/gmail/v1/users/me/'+path,{...options,headers:{Authorization:`Bearer ${await this.token()}`,'Content-Type':'application/json'}}); }
  async profile() { const d=await this.json('profile'); if (d.emailAddress?.toLowerCase()!==SENDER) throw new Error('Gmail must be authorized as team@virventures.com.'); return d.emailAddress; }
  messageId(key) { return `<replyassist.${createHash('sha256').update(key).digest('hex')}@virventures.com>`; }
  async reconcile(job) {
    blockReviewOperation();
    await this.profile();
    const q=new URLSearchParams({q:`in:sent rfc822msgid:${this.messageId(job.key).slice(1,-1)}`,maxResults:'10'});
    const d=await this.json('messages?'+q);
    return d.messages?.[0]?.id || null;
  }
  async send(job) {
    blockReviewOperation();
    if (![HUMAN,POST_ORDER].includes(job.decision.to)) throw new Error('Unexpected alert recipient.');
    await this.profile();
    const when=new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'long',timeZone:'Asia/Kolkata'}).format(new Date(job.receivedAt));
    const subject=`${job.decision.urgent?'URGENT: ':''}ReplyAssist ${job.decision.kind==='post_order'?'post-order question':'human review'} (${job.message})`;
    const body=[`Seller: ${job.seller}`,`Conversation: ${job.conversation}`,`Message: ${job.message}`,`Listing: ${job.itemId ? 'https://www.ebay.com/itm/'+job.itemId : 'not available'}`,`Received (IST): ${when}`,`Reason: ${job.decision.reason}`,`Customer reply status: ${job.replyState}`,`Reply: ${job.decision.text}`,'','Customer question (untrusted customer content):',job.question].join('\r\n');
    const mime=[`From: VirVentures <${SENDER}>`,`To: ${job.decision.to}`,`Subject: =?UTF-8?B?${Buffer.from(subject).toString('base64')}?=`,`Message-ID: ${this.messageId(job.key)}`,`Date: ${new Date().toUTCString()}`,'MIME-Version: 1.0','Content-Type: text/plain; charset=UTF-8','Content-Transfer-Encoding: base64',...(job.decision.urgent?['X-Priority: 1 (Highest)','Importance: high']:[]),'',Buffer.from(body).toString('base64').match(/.{1,76}/g).join('\r\n')].join('\r\n');
    const result=await this.json('messages/send',{method:'POST',body:JSON.stringify({raw:Buffer.from(mime).toString('base64url')})});
    if (!result.id) throw new Error('Gmail response is ambiguous; reconciliation required.');
    return result.id;
  }
  async exchange(code,redirect,verifier) {
    const s=this.vault.load();
    const d=await request('https://oauth2.googleapis.com/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:s.googleClientId,client_secret:s.googleClientSecret || '',code,redirect_uri:redirect,code_verifier:verifier,grant_type:'authorization_code'})});
    if (!d.refresh_token) throw new Error('Google did not grant background access. Reconnect with consent.');
    // Verify the account BEFORE storing its refresh token.
    const p=await request('https://gmail.googleapis.com/gmail/v1/users/me/profile',{headers:{Authorization:`Bearer ${d.access_token}`}});
    if (p.emailAddress?.toLowerCase()!==SENDER) throw new Error('Wrong Gmail account. Use team@virventures.com.');
    this.vault.update({googleRefreshToken:d.refresh_token}); this.invalidate();
  }
}

