import {AsyncLocalStorage} from 'node:async_hooks';
const requestContext=new AsyncLocalStorage();
export const withRequestBudget=(ms,fn)=>requestContext.run(AbortSignal.timeout(ms),fn);
export class ApiError extends Error {
  constructor(service, status, retryAfter = null) { super(`${service} request failed (${status}).`); this.status=status; this.retryAfter=retryAfter; }
}
export async function request(url, options = {}) {
  const signal=AbortSignal.any([options.signal,requestContext.getStore(),AbortSignal.timeout(30000)].filter(Boolean));
  const res = await fetch(url, {...options, redirect:'error', signal});
  if (!res.ok) { await res.body?.cancel(); throw new ApiError(new URL(url).hostname, res.status, res.headers.get('retry-after')); }
  const raw = await res.text();
  if (raw.length>15000000) throw new Error('API response exceeded safe size.');
  return options.responseType === 'text' ? raw : raw ? JSON.parse(raw) : {};
}
export async function paged(fetchPage, initial, field, prefix, maxPages = 500) {
  let url=initial; const output=[]; const seen=new Set();
  for (let n=0; url && n<maxPages; n++) {
    if (!url.startsWith(prefix) || seen.has(url)) throw new Error('Unsafe or repeated pagination URL.');
    seen.add(url);
    const data=await fetchPage(url);
    if (!Array.isArray(data[field]) && data.total!==0) throw new Error('Unexpected paginated API response.');
    output.push(...(data[field] || []));
    url=data.next || null;
    if (!url && Number.isFinite(data.total) && output.length<data.total) throw new Error('Incomplete API pagination.');
  }
  if (url) throw new Error('Pagination limit exceeded; no incomplete data will be used.');
  return output;
}

