import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {privateDirectory} from './security.js';
import {Store} from './store.js';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const data=path.resolve(root,'../../work/replyassist-private-new');
if(process.env.REPLYASSIST_DATA_DIR!==data || !process.env.REPLYASSIST_NORMAL_USER_SID)
  throw new Error('Use the normal-user review setup launcher.');
// No vault is constructed and no credentials are generated or imported.
if(fs.existsSync(data)) throw new Error('Target already exists. Existing or partial data must be preserved.');
privateDirectory(data);
if(fs.readdirSync(data).length) throw new Error('Fresh initialization requires an empty directory. Existing files are preserved.');
const store=new Store(path.join(data,'review.sqlite'));
try {
  store.set('live',false);
  store.set('monitoring',false);
  store.set('recoveryLock',{locked:true,historyAvailable:false,duplicatePreventionValidated:false,cutoffValidated:false});
  store.set('checks',{ok:false,reason:'Fresh eBay test 2 and Gmail authorization required through the dashboard.'});
} finally {store.close();}
fs.writeFileSync(path.join(data,'review-setup.json'),JSON.stringify({version:1,ownerSid:process.env.REPLYASSIST_NORMAL_USER_SID,createdAt:new Date().toISOString(),build:'replyassist-review'}),{flag:'wx',mode:0o600});
console.log('Fresh review database initialized. No credentials or reply history imported.');

