import {createHash} from 'node:crypto';
import {HOLDING, HUMAN, POST_ORDER} from './config.js';
export const fingerprint = c => createHash('sha256').update(JSON.stringify([c.id,c.itemId,c.type,c.complete,c.messages.map(m=>[m.id,m.sender,m.recipient,m.receivedAt,m.text,m.attachments]).sort((a,b)=>a[0].localeCompare(b[0]))])).digest('hex');
export function inOfficeWindow(receivedAt) {
  const t = new Date(receivedAt);
  if (!Number.isFinite(t.getTime())) throw new Error('Missing or invalid received time.');
  const ist = new Date(t.getTime() + 330 * 60000);
  const minute = ist.getUTCHours() * 60 + ist.getUTCMinutes();
  return minute >= 420 && minute < 1080;
}
export function latestCustomer(c, seller) {
  if (!c.complete || c.type !== 'FROM_MEMBERS' || !c.messages.length) return null;
  const sorted = [...c.messages].sort((a,b)=>Date.parse(a.receivedAt)-Date.parse(b.receivedAt));
  const newest = sorted.at(-1);
  if (newest.sender.toLowerCase() === seller.toLowerCase() || newest.recipient.toLowerCase() !== seller.toLowerCase()) return null;
  // Same timestamp gives no reliable ordering: treat a staff reply as authoritative.
  if (sorted.some(m=>m.sender.toLowerCase()===seller.toLowerCase() && Date.parse(m.receivedAt)>=Date.parse(newest.receivedAt))) return null;
  return newest;
}
const postClue = /\b(my order|order number|ordered|purchased|bought|tracking|refund|return|cancel|cancellation|received|delivered|delivery status|not arrived|hasn.t arrived|damaged|missing parts|replacement|where is my|where.s my)\b/i;
const preamble = /^(?:hi[,.!]?\s*)?(?:before (?:i (?:buy|order|purchase)|buying|ordering|purchasing)[,.!:]?\s*)/i;
const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();

// Deliberately bounded extractive answers. No LLM, suggested eBay.ai draft,
// arbitrary customer instruction, fitment inference or generated product claim.
export function supportedFact(c, listing, message) {
  if (!listing || !listing.active || !listing.complete || listing.multiVariation || listing.itemId !== c.itemId || !Number.isFinite(Date.parse(listing.fetchedAt)) || Date.parse(listing.fetchedAt)>Date.now()+5000 || Date.now()-Date.parse(listing.fetchedAt)>120000) return null;
  const inbound = c.messages.filter(m=>m.sender===message.sender);
  if (inbound.length !== 1 || c.messages.length !== 1 || message.attachments.length) return null;
  const q = message.text.replace(preamble,'').trim();
  const match = /^(?:what (?:is|are)(?: the)?|which) (brand|material|colou?r|finish|model)(?: (?:is this|is it|of (?:this|the) (?:item|product)|does (?:this|the) (?:item|product) have))?\s*\?*$/i.exec(q);
  if (!match) return null;
  const property = match[1].toLowerCase().replace('colour','color');
  const candidates = listing.specifics.filter(s=>norm(s.name).replace('colour','color')===property);
  if (candidates.length!==1 || candidates[0].values.length!==1) return null;
  const value = candidates[0].values[0];
  if (!value || value.length>100 || /[<>\r\n]|https?:|ignore|instruction|unspecified|does not apply|varies|unknown/i.test(value)) return null;
  // Automatic conflict checking cannot establish consistency for arbitrary prose.
  // Require the entire description to consist only of the structured item facts.
  // All free-form descriptions, alternative variants and mixed context go to review.
  const allowed = new Set(listing.specifics.flatMap(s=>s.values.map(v=>norm(`${s.name} ${v}`))));
  const lines = listing.description.split(/[\n;]+/).map(norm).filter(Boolean);
  if (!lines.length || lines.some(l=>!allowed.has(l))) return null;
  // Title is also listing evidence. Only accept a factual title built from the
  // same structured values; unknown title prose requires a human conflict check.
  let title = norm(listing.title);
  for (const v of listing.specifics.flatMap(s=>s.values).sort((a,b)=>b.length-a.length)) title = title.replaceAll(norm(v),' ');
  if (norm(title)) return null;
  return {text:`Thank you for contacting VirVentures. The current listing specifies ${candidates[0].name}: ${value}.`, evidence:[{itemId:listing.itemId,field:candidates[0].name,value,fetchedAt:listing.fetchedAt}]};
}
export function decide({conversation:c, listing, message:m, matchedOrder, orderLookupOk}) {
  const allCustomerText = c.messages.filter(x=>x.sender===m.sender).map(x=>x.text).join('\n');
  const post = matchedOrder || postClue.test(allCustomerText);
  if (post) return {kind:'post_order',text:HOLDING,to:inOfficeWindow(m.receivedAt)?POST_ORDER:null,urgent:true,reason:matchedOrder?'Buyer and item match an order.':'Customer conversation indicates a post-order issue.',evidence:[]};
  const explicitPre = preamble.test(m.text);
  if (explicitPre && orderLookupOk) {
    const answer = supportedFact(c,listing,m);
    if (answer) return {kind:'supported_answer',...answer,to:null,urgent:false,reason:'Exact pre-purchase question supported by consistent current listing fields and complete conversation.'};
  }
  return {kind:'human_review',text:HOLDING,to:HUMAN,urgent:false,reason:!orderLookupOk?'Order access could not be verified.':!explicitPre?'Order relationship or customer intent needs review.':'Listing evidence, variant, conversation or question requires human review.',evidence:[]};
}

