export const REVIEW_LOCK_REASON = 'Review lock: customer replies, email sending, live activation and automatic monitoring are permanently blocked in this build.';
export function blockReviewOperation() { throw new Error(REVIEW_LOCK_REASON); }
export function isBlockedReviewRoute(route) {
  return ['/api/activate','/api/resolve'].includes(route);
}

