import {decide,fingerprint,latestCustomer} from './policy.js';
import {HOLDING} from './config.js';
import {safeError} from './engine.js';

export class ReviewRun {
  constructor({store,ebay,clock=()=>Date.now()}) { this.store=store; this.ebay=ebay; this.clock=clock; }
  arm() {
    const s=this.store;
    const prior=s.get('reviewCutoff');
    if(prior) return this.window(); // Never move a cutoff backwards or silently reset it.
    const cutoff=new Date(this.clock()).toISOString();
    s.set('reviewCutoff',cutoff);
    return this.window();
  }
  window() {
    const cutoff=this.store.get('reviewCutoff'), start=Date.parse(cutoff), now=this.clock();
    if(!Number.isFinite(start) || now<start) throw new Error('Review cutoff missing, invalid or in the future.');
    return {cutoff,end:new Date(Math.min(now,start+86400000)).toISOString(),expiresAt:new Date(start+86400000).toISOString()};
  }
  requireChecks() {
    const s=this.store,c=s.get('checks'), age=this.clock()-Date.parse(c?.at);
    if(!s.get('seller') || !c?.ebay || !c?.orders || !c?.listing || !c?.gmail || !Number.isFinite(age) || age<0 || age>900000)
      throw new Error('Verify seller, orders, listing and Gmail again before read-only validation.');
  }
  async checkAccess() {
    this.requireChecks();
    const w=this.window(), signal=AbortSignal.timeout(120000);
    const result={at:new Date(this.clock()).toISOString(),seller:this.store.get('seller'),cutoff:w.cutoff,ok:false,fullConversation:false};
    this.store.set('messageAccess',result);
    try {
      const page=await this.ebay.reviewPage(w.cutoff,w.end,signal);
      result.summaryAccess=true; result.truncated=page.truncated;
      if(page.summaries.length) {
        const c=await this.ebay.reviewConversation(page.summaries[0],signal);
        if(!c.complete) throw new Error('Incomplete conversation.');
        result.fullConversation=true;
      }
      result.ok=true;
      result.note=result.fullConversation?'Summary and full conversation reads passed.':'Summary access passed; no conversations returned. Full-conversation access remains untested.';
    } catch(e) {result.error=safeError(e);}
    this.store.set('messageAccess',result);return result;
  }
  async run() {
    this.requireChecks();
    const s=this.store,w=this.window(),seller=s.get('seller').toLowerCase(),access=s.get('messageAccess');
    const age=this.clock()-Date.parse(access?.at);
    if(!access?.ok || access.cutoff!==w.cutoff || access.seller?.toLowerCase()!==seller || !Number.isFinite(age) || age<0 || age>900000)
      throw new Error('Verify read-only message access again before the dry run.');
    const signal=AbortSignal.timeout(120000);
    const report={at:new Date(this.clock()).toISOString(),...w,mode:'bounded_read_only',processed:0,duplicates:0,skipped:0,failures:0,fullConversations:0,listingGaps:0,truncated:false,complete:false,details:[]};
    s.set('reviewRun', {...report,inProgress:true});
    try {
      const page=await this.ebay.reviewPage(w.cutoff,w.end,signal);
      report.truncated=page.truncated || page.summaries.length>10;
      const seen=new Set();
      for(const summary of page.summaries.slice(0,10)) {
        if(seen.has(summary.conversationId)) {report.duplicates++;continue;}
        seen.add(summary.conversationId);
        // Retire stale proposals before attempting a new complete read.
        s.invalidateProposals(seller,summary.conversationId,'not_revalidated');
        try {
          signal.throwIfAborted();
          const c=await this.ebay.reviewConversation(summary,signal);
          if(!c.complete || c.id!==summary.conversationId || c.messages.some(m=>!Number.isFinite(Date.parse(m.receivedAt)))) throw new Error('Incomplete conversation evidence.');
          report.fullConversations++;
          const m=latestCustomer(c,seller), t=Date.parse(m?.receivedAt);
          if(!m || !Number.isFinite(t) || t<Date.parse(w.cutoff) || t>Date.parse(w.end)) {
            report.skipped++;
            report.details.push({conversation:c.id,skipped:!m?'No eligible latest customer message (including staff/system threads).':t<Date.parse(w.cutoff)?'Before processing cutoff.':'After fixed run end or invalid time.'});
            continue;
          }
          let listing=null,listingError=null;
          if(c.itemId) {
            try {
              listing=await this.ebay.listing(c.itemId,signal);
              if(listing.seller?.toLowerCase()!==seller || listing.itemId!==c.itemId) throw new Error('Listing identity mismatch.');
              const age=this.clock()-Date.parse(listing.fetchedAt);
              if(!listing.complete || !Number.isFinite(age) || age < -5000 || age>120000) throw new Error('Incomplete or stale listing evidence.');
            }
            catch(e) {listing=null;listingError=safeError(e);}
          } else listingError='Missing listing reference; human review required.';
          if(!listing) {report.listingGaps++;report.details.push({conversation:c.id,listingError});}
          signal.throwIfAborted();
          // No order index is inferred from a successful permission check.
          const decision=decide({conversation:c,listing,message:m,matchedOrder:s.orderMatch(m.sender,c.itemId),orderLookupOk:false});
          const priorHolding=c.messages.some(x=>x.sender.toLowerCase()===seller && x.text.trim().replace(/\s+/g,' ')===HOLDING.trim().replace(/\s+/g,' '));
          const key=JSON.stringify([seller,c.id,m.id]);
          const prior=s.proposal(key),hash=fingerprint(c);
          if(prior) report.duplicates++;
          const p={key,seller,conversation:c.id,message:m.id,itemId:c.itemId,receivedAt:m.receivedAt,question:m.text,decision,conversationHash:hash,cutoff:w.cutoff,createdAt:prior?.createdAt || report.at,checkedAt:new Date(this.clock()).toISOString(),dryRun:true,replyState:priorHolding?'would_suppress_prior_holding':'proposal_only',emailState:'blocked',recoveryReviewRequired:true,priorHolding,listingError,evidence:{conversation:c,listing},note:'Old ledger unavailable. Manual recovery review required; never eligible for dispatch.'};
          s.saveProposal(p);report.processed++;
        } catch(e) {report.failures++;report.details.push({conversation:summary.conversationId,error:safeError(e)});}
        if(signal.aborted) break;
      }
      report.complete=!report.truncated && !report.failures && !report.listingGaps && !signal.aborted;
    } catch(e) {report.failures++;report.error=safeError(e);}
    s.set('reviewRun',report);return report;
  }
}

