import {spawnSync} from 'node:child_process';
import fs from 'node:fs';
export function privateDirectory(directory) {
  // Creation and restriction happen only after the Windows identity check below.
  if(process.platform!=='win32') throw new Error('Windows is required for this build.');
  // Read and update only the DACL: writing a new security descriptor can
  // request audit privileges that a normal Windows account does not have.
  const script=`
$ErrorActionPreference='Stop'
$p=[Console]::In.ReadToEnd()
$identity=[Security.Principal.WindowsIdentity]::GetCurrent()
$sid=$identity.User
if($env:REPLYASSIST_NORMAL_USER_SID -ne $sid.Value -or $identity.Name -match 'CodexSandbox' -or $env:USERPROFILE -ne 'C:\\Users\\ANANGSHA HALDER' -or $sid.Value -eq 'S-1-5-18'){throw 'Normal Windows account required.'}
$systemSid=New-Object Security.Principal.SecurityIdentifier('S-1-5-18')
if(!(Test-Path -LiteralPath $p)){New-Item -ItemType Directory -Path $p -ErrorAction Stop | Out-Null}
$dir=Get-Item -LiteralPath $p
if($dir.Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Private directory must not be a link.'}
$acl=$dir.GetAccessControl([Security.AccessControl.AccessControlSections]::Access -bor [Security.AccessControl.AccessControlSections]::Owner)
if($acl.GetOwner([Security.Principal.SecurityIdentifier]).Value -ne $sid.Value){throw 'Private directory belongs to another Windows account.'}
function IsPrivate($a) {
  $rules=@($a.GetAccessRules($true,$true,[Security.Principal.SecurityIdentifier]))
  if(!$a.AreAccessRulesProtected -or $rules.Count -ne 2){return $false}
  foreach($id in @($sid.Value,$systemSid.Value)) {
    $match=@($rules | Where-Object { $_.IdentityReference.Value -eq $id -and $_.AccessControlType -eq 'Allow' -and $_.FileSystemRights -eq 'FullControl' -and $_.InheritanceFlags -eq 'ContainerInherit,ObjectInherit' -and $_.PropagationFlags -eq 'None' })
    if($match.Count -ne 1){return $false}
  }
  return $true
}
if(IsPrivate $acl){exit 0}
$acl.SetAccessRuleProtection($true,$false)
foreach($rule in @($acl.GetAccessRules($true,$false,[Security.Principal.SecurityIdentifier]))){$acl.RemoveAccessRuleSpecific($rule)}
$rule=New-Object Security.AccessControl.FileSystemAccessRule($sid,'FullControl','ContainerInherit,ObjectInherit','None','Allow')
$acl.AddAccessRule($rule)
$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($systemSid,'FullControl','ContainerInherit,ObjectInherit','None','Allow')))
$dir.SetAccessControl($acl)
if(!(IsPrivate ($dir.GetAccessControl([Security.AccessControl.AccessControlSections]::Access)))){throw 'Private directory verification failed.'}
`;
  const r=spawnSync('powershell.exe',['-NoProfile','-NonInteractive','-Command',script],{input:directory,encoding:'utf8',windowsHide:true,timeout:15000});
  if(r.status!==0) throw new Error('Windows could not restrict the private data directory.');
}
export function validRequest(req,origin,csrf) {
  if(req.headers.host!==new URL(origin).host) return false;
  if(req.method==='POST') return req.headers.origin===origin && req.headers['x-replyassist-csrf']===csrf && req.headers['content-type']==='application/json';
  return !req.headers.origin || req.headers.origin===origin;
}
export async function body(req) {
  let bytes=0, chunks=[];
  for await (const chunk of req) { bytes+=chunk.length;if(bytes>100000) throw new Error('Request too large.');chunks.push(chunk); }
  return JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}');
}

