import http from 'node:http';
import {isBlockedReviewRoute,REVIEW_LOCK_REASON} from './review-lock.js';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {randomBytes,createHash} from 'node:crypto';
import {spawn} from 'node:child_process';
import {Vault} from './vault.js';
import {Store} from './store.js';
import {Ebay} from './ebay.js';
import {Gmail} from './gmail.js';
import {Engine,safeError} from './engine.js';
import {ReviewRun} from './review-run.js';
import {createSession} from './session.js';
import {privateDirectory,validRequest,body} from './security.js';
import {CLIENT_ID,KEYSET,SENDER,EBAY_SCOPES,GOOGLE_SCOPES,PORT,ORIGIN} from './config.js';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const data=path.resolve(root,'../../work/replyassist-private-new');
if(process.env.REPLYASSIST_DATA_DIR !== data || !process.env.REPLYASSIST_NORMAL_USER_SID) throw new Error('Use Start-ReplyAssist-Review.ps1 from your normal Windows account.');
if(!fs.existsSync(path.join(data,'review-setup.json'))) throw new Error('Run the normal-user review setup first.');
privateDirectory(data);
const vault=new Vault(data), store=new Store(path.join(data,'review.sqlite'));
store.set('live',false); store.set('monitoring',false);
store.set('recoveryLock',{locked:true,historyAvailable:false,duplicatePreventionValidated:false,cutoffValidated:false});
const ebay=new Ebay(vault),gmail=new Gmail(vault);
const csrf=randomBytes(32).toString('hex');
const dashboardSession=createSession(ORIGIN);
let lastVerified=0, actionBusy=false;
// Each restart requires a fresh connection check before any live traffic.
store.set('checks',{ok:false,at:new Date().toISOString(),reason:'Fresh connection check required after startup.'});
const engine=new Engine({store,ebay,gmail,canSend:()=>false});
const reviewRunner=new ReviewRun({store,ebay});
const oauth=new Map();
const send=(res,status,obj)=>{res.writeHead(status,{'Content-Type':'application/json; charset=utf-8'});res.end(JSON.stringify(obj));};
function status() {return {reviewLocked:true,keyset:KEYSET,clientId:CLIENT_ID,from:SENDER,live:store.get('live',false),monitoring:store.get('monitoring',false),seller:store.get('seller'),credentials:vault.status(),checks:store.get('checks'),lastPoll:store.get('lastPoll'),tests:store.get('tests'),activationAt:store.get('activationAt'),runame:store.get('runame','test-test-test2-PRD--moseuetr'),reviewCutoff:store.get('reviewCutoff'),messageAccess:store.get('messageAccess'),reviewRun:store.get('reviewRun'),review:store.jobs(),dryRun:store.proposals(),events:store.events(),csrf};}
async function verify() {
  const result={at:new Date().toISOString(),ok:false,ebay:false,gmail:false,messages:false,orders:false,listing:false};
  try {
    await ebay.token(true);
    const seller=await ebay.identity(), prior=store.get('seller');
    if(prior && prior.toLowerCase()!==seller.toLowerCase()) throw new Error('Account changed; use a separate data directory for a different seller.');
    store.set('seller',seller);result.ebay=true;result.seller=seller;
    const end=new Date().toISOString();
    result.messageCheckDeferred='Use the separate read-only message-access check after establishing a cutoff.';
    await ebay.orders(new Date(Date.now()-86400000).toISOString(),end); result.orders=true;
    const item=store.get('testItemId');
    if(item) {const listing=await ebay.listing(String(item));if(listing.seller.toLowerCase()!==seller.toLowerCase()) throw new Error('Listing identity does not match seller.');result.listing=true;result.testItemId=String(item);store.set('testItemId',String(item));}
    else result.listingError='An item ID from this seller is needed for the listing access check.';
  } catch(e) {result.ebayError=safeError(e);}
  try {await gmail.token(true);await gmail.profile();result.gmail=true;} catch(e) {result.gmailError=safeError(e);}
  result.ok=!!(result.ebay && result.orders && result.listing && result.gmail);
  store.set('messageAccess',null); store.set('checks',result); if(result.ok) lastVerified=Date.now();
  store.log('connection_check',{...result});return result;
}
async function selfTest() {
  const result=await new Promise(resolve=>{
    const child=spawn(process.execPath,['--test','test/policy.test.js','test/security.test.js','test/review-lock.test.js','test/review-run.test.js','test/session.test.js'],{cwd:root,windowsHide:true,stdio:['ignore','pipe','pipe']});
    let output='';child.stdout.on('data',d=>output+=d);child.stderr.on('data',d=>output+=d);
    child.on('error',()=>resolve({ok:false,output:'Unable to launch tests.'}));
    child.on('exit',code=>resolve({ok:code===0,output:output.slice(-18000)}));
  });
  const saved={...result,version:'read-only-v2',at:new Date().toISOString()};store.set('tests',saved);return saved;
}
function consumeState(state,provider) {
  const pending=oauth.get(state);oauth.delete(state);
  if(!pending || pending.provider!==provider || Date.now()-pending.created>10*60000) throw new Error('Invalid or expired authorization state. Start again.');
  return pending;
}
const server=http.createServer(async(req,res)=>{
  res.setHeader('Cache-Control','no-store');res.setHeader('Referrer-Policy','no-referrer');res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('X-Frame-Options','DENY');
  res.setHeader('Content-Security-Policy',"default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'");
  try {
    if(req.headers.host!==`127.0.0.1:${PORT}`) return send(res,403,{error:'Invalid host.'});
    const url=new URL(req.url,ORIGIN);
    const authenticated=dashboardSession.authenticated(req);
    if(req.method==='GET' && url.pathname==='/api/instance') return send(res,200,{build:'replyassist-review',instanceId:dashboardSession.instanceId,pid:process.pid});
    if(req.method==='GET' && url.pathname==='/oauth/google/callback') {
      const pending=consumeState(url.searchParams.get('state'),'google');
      if(url.searchParams.has('error')) throw new Error('Google did not grant access.');
      await gmail.exchange(url.searchParams.get('code'),ORIGIN+'/oauth/google/callback',pending.verifier);
      store.set('checks',{ok:false,at:new Date().toISOString()});
      res.writeHead(303,{Location:'/'});return res.end();
    }
    if(url.pathname==='/api/session') return await dashboardSession.bootstrap(req,res);
    const assets={'/':'index.html','/app.js':'app.js','/style.css':'style.css'};
    if(req.method==='GET' && assets[url.pathname]) {
      const name=assets[url.pathname];res.writeHead(200,{'Content-Type':name.endsWith('.js')?'text/javascript':name.endsWith('.css')?'text/css':'text/html; charset=utf-8'});return res.end(fs.readFileSync(path.join(root,'public',name)));
    }
    if(!authenticated || !validRequest(req,ORIGIN,csrf)) return send(res,403,{error:'Session missing or expired. Run Open-ReplyAssist-Review.ps1 for the current server.'});
    if(req.method==='GET' && url.pathname==='/api/status') return send(res,200,status());
    if(req.method!=='POST') return send(res,404,{error:'Not found.'});
    const input=await body(req);
    if(isBlockedReviewRoute(url.pathname)) return send(res,423,{error:REVIEW_LOCK_REASON});
    if(url.pathname==='/api/pause') {store.set('live',false);store.set('monitoring',false);store.log('paused',{});return send(res,200,{ok:true});}
    if(actionBusy || engine.busy) return send(res,409,{error:'A check or polling cycle is in progress. Please try again shortly.'});
    actionBusy=true;
    try {
      if(url.pathname==='/api/credentials/ebay') {
        if(input.clientId!==CLIENT_ID || !input.secret || /\s|•/.test(input.secret)) throw new Error('Only the complete test 2 Cert ID can be saved.');
        store.set('live',false);store.set('checks',{ok:false});
        vault.update({ebayClientId:CLIENT_ID,ebaySecret:input.secret});ebay.invalidate();return send(res,200,{ok:true});
      }
      if(url.pathname==='/api/credentials/google') {
        const installed=input.client?.installed;
        if(!installed?.client_id?.endsWith('.apps.googleusercontent.com') || !installed.client_secret) throw new Error('Save a Google Desktop OAuth client JSON file.');
        store.set('live',false);store.set('checks',{ok:false});
        vault.update({googleClientId:installed.client_id,googleClientSecret:installed.client_secret,googleRefreshToken:null});gmail.invalidate();return send(res,200,{ok:true});
      }
      if(url.pathname==='/api/authorize/ebay') {
        if(!vault.status().ebayClient) throw new Error('Save the test 2 Cert ID first.');
        if(!/^test-test-test2-PRD--[\w-]+$/.test(input.runame)) throw new Error('Only a redirect name for test 2 is allowed.');
        store.set('runame',input.runame);
        const state=randomBytes(32).toString('hex');oauth.set(state,{provider:'ebay',created:Date.now(),runame:input.runame});
        return send(res,200,{url:'https://auth.ebay.com/oauth2/authorize?'+new URLSearchParams({client_id:CLIENT_ID,response_type:'code',redirect_uri:input.runame,scope:EBAY_SCOPES.join(' '),state})});
      }
      if(url.pathname==='/api/authorize/ebay/complete') {
        // For eBay's default HTTPS success page, enter the returned URL into
        // this local password field. It is never recorded in the review log.
        const callback=new URL(input.callback);
        if(callback.protocol!=='https:' || !['auth.ebay.com','auth2.ebay.com'].includes(callback.hostname)) throw new Error('Only the eBay authorization result URL is accepted.');
        const pending=consumeState(callback.searchParams.get('state'),'ebay');
        if(!callback.searchParams.get('code')) throw new Error('No eBay authorization code found.');
        await ebay.exchange(callback.searchParams.get('code'),pending.runame);store.set('checks',{ok:false});return send(res,200,{ok:true});
      }
      if(url.pathname==='/api/authorize/google') {
        const secrets=vault.load();if(!secrets.googleClientId) throw new Error('Save the Google Desktop OAuth client first.');
        const state=randomBytes(32).toString('hex'),verifier=randomBytes(48).toString('base64url');
        oauth.set(state,{provider:'google',created:Date.now(),verifier});
        return send(res,200,{url:'https://accounts.google.com/o/oauth2/v2/auth?'+new URLSearchParams({client_id:secrets.googleClientId,redirect_uri:ORIGIN+'/oauth/google/callback',response_type:'code',scope:GOOGLE_SCOPES.join(' '),access_type:'offline',prompt:'consent',login_hint:SENDER,state,code_challenge:createHash('sha256').update(verifier).digest('base64url'),code_challenge_method:'S256'})});
      }
      if(url.pathname==='/api/verify') {if(input.itemId) {if(!/^\d+$/.test(input.itemId)) throw new Error('Invalid listing ID.');store.set('testItemId',input.itemId);}return send(res,200,await verify());}
      if(url.pathname==='/api/test') return send(res,200,await selfTest());
      if(['/api/review-cutoff','/api/message-access','/api/dry-run'].includes(url.pathname)) {
        if(!store.get('tests')?.ok || store.get('tests').version!=='read-only-v2') throw new Error('Review validation: run the updated offline tests first.');
        reviewRunner.requireChecks();
        if(url.pathname==='/api/review-cutoff') return send(res,200,reviewRunner.arm());
        if(url.pathname==='/api/message-access') return send(res,200,await reviewRunner.checkAccess());
        return send(res,200,await reviewRunner.run());
      }
      return send(res,404,{error:'Not found.'});
    } finally {actionBusy=false;}
  } catch(e) {send(res,400,{error:safeError(e)});}
});
