import {randomBytes,timingSafeEqual} from 'node:crypto';
import {body} from './security.js';

const same=(a,b)=>typeof a==='string' && /^[a-f0-9]{64}$/.test(a) && timingSafeEqual(Buffer.from(a,'ascii'),Buffer.from(b,'ascii'));
export function createSession(origin) {
  const launchKey=randomBytes(32).toString('hex'),cookie=randomBytes(32).toString('hex');
  const instanceId=randomBytes(16).toString('hex'); // Public boot identifier, not an authentication credential.
  return {
    instanceId,
    launchUrl:origin+'/?instance='+instanceId+'#'+launchKey,
    authenticated(req) {return (req.headers.cookie || '').split(';').some(c=>c.trim()===`replyassist=${cookie}`);},
    async bootstrap(req,res) {
      const reply=(code,value)=>{res.writeHead(code,{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'});res.end(JSON.stringify(value));};
      if(req.method!=='POST' || req.headers.host!==new URL(origin).host || req.headers.origin!==origin || req.headers['content-type']!=='application/json') {
        reply(403,{error:'Invalid session request origin.'});return;
      }
      let input;
      try {input=await body(req);} catch {reply(400,{error:'Invalid session request.'});return;}
      if(input.instanceId!==instanceId || !same(input.key,launchKey)) {
        reply(403,{error:'This launch link is stale or invalid. Run Open-ReplyAssist-Review.ps1 for the current server.'});return;
      }
      res.setHeader('Set-Cookie',`replyassist=${cookie}; HttpOnly; SameSite=Strict; Path=/`);
      reply(200,{ok:true,instanceId});
    }
  };
}

