import {DatabaseSync} from 'node:sqlite';
export class Store {
  constructor(filename) {
    this.db = new DatabaseSync(filename);
    this.db.exec(`PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL; PRAGMA busy_timeout=5000;
      CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS jobs (key TEXT PRIMARY KEY, seller TEXT NOT NULL, conversation TEXT NOT NULL, message TEXT NOT NULL, created TEXT NOT NULL, payload TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS issues (key TEXT PRIMARY KEY, payload TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY, at TEXT NOT NULL, kind TEXT NOT NULL, detail TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, buyer TEXT NOT NULL, items TEXT NOT NULL, created TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS review_proposals (key TEXT PRIMARY KEY, seller TEXT NOT NULL, conversation TEXT NOT NULL, payload TEXT NOT NULL);`);
  }
  get(key, fallback = null) { const r = this.db.prepare('SELECT value FROM settings WHERE key=?').get(key); return r ? JSON.parse(r.value) : fallback; }
  set(key, value) { this.db.prepare('INSERT INTO settings VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').run(key, JSON.stringify(value)); }
  log(kind, detail) { this.db.prepare('INSERT INTO events(at,kind,detail) VALUES (?,?,?)').run(new Date().toISOString(), kind, JSON.stringify(detail)); }
  events() { return this.db.prepare('SELECT * FROM events ORDER BY id DESC LIMIT 100').all(); }
  job(key) { const r = this.db.prepare('SELECT payload FROM jobs WHERE key=?').get(key); return r ? JSON.parse(r.payload) : null; }
  insert(job) { return this.db.prepare('INSERT OR IGNORE INTO jobs VALUES (?,?,?,?,?,?)').run(job.key, job.seller, job.conversation, job.message, new Date().toISOString(), JSON.stringify(job)).changes === 1; }
  save(job) { this.db.prepare('UPDATE jobs SET payload=? WHERE key=?').run(JSON.stringify(job), job.key); }
  jobs(limit = 200) { return this.db.prepare('SELECT payload FROM jobs ORDER BY rowid DESC LIMIT ?').all(limit).map(r => JSON.parse(r.payload)); }
  pending() { return this.db.prepare('SELECT payload FROM jobs').all().map(r => JSON.parse(r.payload)).filter(j => ['pending','sending','unknown'].includes(j.emailState) || ['sending','unknown'].includes(j.replyState)); }
  issue(seller, conversation) { const r = this.db.prepare('SELECT payload FROM issues WHERE key=?').get(`${seller}:${conversation}`); return r ? JSON.parse(r.payload) : null; }
  setIssue(seller, conversation, issue) { this.db.prepare('INSERT INTO issues VALUES (?,?) ON CONFLICT(key) DO UPDATE SET payload=excluded.payload').run(`${seller}:${conversation}`, JSON.stringify(issue)); }
  addOrder(order) {
    if (!order.orderId || !order.buyer?.username || !Array.isArray(order.lineItems)) throw new Error('Unexpected order response.');
    this.db.prepare('INSERT INTO orders VALUES (?,?,?,?) ON CONFLICT(id) DO UPDATE SET buyer=excluded.buyer,items=excluded.items,created=excluded.created').run(order.orderId, order.buyer.username.toLowerCase(), JSON.stringify(order.lineItems.map(i=>String(i.legacyItemId || ''))), order.creationDate);
  }
  orderMatch(buyer, item) { return this.db.prepare('SELECT * FROM orders WHERE buyer=?').all(buyer.toLowerCase()).some(r => !item || JSON.parse(r.items).includes(item)); }
  close() { this.db.close(); }
  proposals() { return this.db.prepare('SELECT payload FROM review_proposals ORDER BY rowid DESC LIMIT 200').all().map(r=>JSON.parse(r.payload)); }
  proposal(key) { const r=this.db.prepare('SELECT payload FROM review_proposals WHERE key=?').get(key); return r ? JSON.parse(r.payload) : null; }
  saveProposal(p) { this.db.prepare('INSERT INTO review_proposals VALUES (?,?,?,?) ON CONFLICT(key) DO UPDATE SET payload=excluded.payload').run(p.key,p.seller,p.conversation,JSON.stringify(p)); }
  invalidateProposals(seller,conversation,reason) {
    for(const r of this.db.prepare('SELECT payload FROM review_proposals WHERE seller=? AND conversation=?').all(seller,conversation)) {
      const p=JSON.parse(r.payload); p.replyState=reason; p.emailState='blocked'; this.saveProposal(p);
    }
  }
}

