import {spawnSync} from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

// DPAPI is bound to the signed-in Windows user. Secrets go through stdin,
// never command arguments, environment variables, application logs or URLs.
function protect(value, decrypt = false) {
  if (process.platform !== 'win32') throw new Error('Windows DPAPI is required for credential storage.');
  if (!process.env.REPLYASSIST_NORMAL_USER_SID || /CodexSandbox/i.test(process.env.USERNAME || '') || process.env.USERPROFILE?.toLowerCase() !== 'c:\\users\\anangsha halder') throw new Error('Windows normal-user launcher is required for credential access.');
  const operation = decrypt ? 'Unprotect' : 'Protect';
  const script = `Add-Type -AssemblyName System.Security; $v=[Console]::In.ReadToEnd(); $b=[Convert]::FromBase64String($v); $r=[Security.Cryptography.ProtectedData]::${operation}($b,$null,[Security.Cryptography.DataProtectionScope]::CurrentUser); [Console]::Out.Write([Convert]::ToBase64String($r))`;
  const result = spawnSync('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', script], {input: Buffer.from(value).toString('base64'), encoding: 'utf8', windowsHide: true, timeout: 15000});
  if (result.status !== 0) throw new Error('Windows credential encryption failed.');
  return Buffer.from(result.stdout.trim(), 'base64');
}
export class Vault {
  constructor(directory) { this.file = path.join(directory, 'credentials.dpapi'); }
  load() { return fs.existsSync(this.file) ? JSON.parse(protect(fs.readFileSync(this.file), true).toString('utf8')) : {}; }
  save(values) {
    const encrypted = protect(Buffer.from(JSON.stringify(values)));
    fs.writeFileSync(this.file + '.tmp', encrypted, {mode: 0o600});
    fs.renameSync(this.file + '.tmp', this.file);
  }
  update(patch) { this.save({...this.load(), ...patch}); }
  status() { const s = this.load(); return {ebayClient: !!s.ebaySecret, ebaySeller: !!s.ebayRefreshToken, googleClient: !!s.googleClientId, gmail: !!s.googleRefreshToken}; }
}

