const request=(token,extra={})=>new Request(cfg.origin+'/api/status',{headers:{cookie:'__Host-replyassist='+token,...extra}});
test('cloud session rejects forged, expired and rotated-password cookies',()=>{const token=session(cfg,1000);assert.ok(authenticate(request(token),cfg,2000).csrf);assert.throws(()=>authenticate(request(token+'x'),cfg,2000));assert.throws(()=>authenticate(request(token),cfg,1000+8*3600000));assert.throws(()=>authenticate(request(token),{...cfg,password:'different-password-which-is-long'},2000));});
test('CSRF is bound to the session and origin',()=>{const token=session(cfg),auth=authenticate(request(token),cfg);const post=(origin,csrf)=>new Request(cfg.origin+'/api/cutoff',{method:'POST',headers:{origin,'content-type':'application/json','x-csrf':csrf}});assert.doesNotThrow(()=>requirePost(post(cfg.origin,auth.csrf),cfg,auth));assert.throws(()=>requirePost(post('https://evil.example',auth.csrf),cfg,auth));assert.throws(()=>requirePost(post(cfg.origin,'bad'),cfg,auth));});
test('encrypted cloud state detects tampering and wrong encryption keys',()=>{const data={secrets:{value:'unit-test-only'},snapshot:{}};const encrypted=seal(data,cfg);assert.ok(!encrypted.includes('unit-test-only'));assert.deepEqual(unseal(encrypted,cfg),data);assert.throws(()=>unseal(encrypted,{...cfg,key:Buffer.alloc(32)}));const parts=encrypted.split('.');parts[1]=Buffer.alloc(16).toString('base64');assert.throws(()=>unseal(parts.join('.'),cfg));});
test('snapshot round trip preserves cutoff and proposal deduplication',()=>{const a=restore();a.set('reviewCutoff','2026-10-26T00:00:00Z');const p={key:'seller:conversation:message',seller:'seller',conversation:'conversation',question:'first'};a.saveProposal(p);const b=restore(snapshot(a));assert.equal(b.get('reviewCutoff'),'2026-10-26T00:00:00Z');b.saveProposal({...p,question:'updated'});assert.equal(b.proposals().length,1);assert.equal(b.proposal(p.key).question,'updated');a.close();b.close();});
test('unknown and send actions fail before provider access',async()=>{for(const name of ['activate','send','monitor','resolve'])await assert.rejects(action(name,{}, {store:restore(),state:{},vault:{}},cfg,'session'),/unavailable/);});
