  const ebay={conversation:async()=>structuredClone(current),listing:async()=>listing(),send:async()=>{replyCount++;return 'outgoing-1';}};
  const gmail={send:async()=>{emailCount++;return 'email-1';},reconcile:async()=>null};
  const engine=new Engine({store,ebay,gmail});
  return {store,ebay,gmail,engine,counts:()=>[replyCount,emailCount],set:c=>current=c};
}
