import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {Engine} from '../src/engine.js';
import {Ebay} from '../src/ebay.js';
import {Gmail} from '../src/gmail.js';
import {isBlockedReviewRoute} from '../src/review-lock.js';
const trap=new Proxy({}, {get(){throw new Error('Unexpected access to data or network');}});
test('engine blocks every processing entry point before data or provider access',async()=>{
  const engine=new Engine({store:trap,ebay:trap,gmail:trap,canSend:()=>true});
  for(const [method,args] of [['poll',[]],['process',[{},{}]],['email',[{}]],['reconcile',[]],['syncOrders',[]]])
    await assert.rejects(()=>engine[method](...args),/Review lock/);
});
test('both provider dispatch paths reject even valid sends before credentials or network',async()=>{
  const e=new Ebay(trap),g=new Gmail(trap);
  await assert.rejects(()=>e.send('id','reply'),/Review lock/);
  await assert.rejects(()=>g.send({decision:{to:'anangsha.h@virventures.com'}}),/Review lock/);
  await assert.rejects(()=>e.json('https://api.ebay.com/commerce/message/v1/send_message',{method:'POST'}),/Review lock/);
  await assert.rejects(()=>g.json('messages/send',{method:'POST'}),/Review lock/);
});
test('historical reads and reconciliation cannot reach providers',async()=>{
  const e=new Ebay(trap),g=new Gmail(trap);
  for(const call of [()=>e.conversations('old','now'),()=>e.conversation({}),()=>g.reconcile({}),()=>g.json('messages?q=old')])
    await assert.rejects(call,/Review lock/);
});
test('activation, monitoring and resolve routes locked while authorization remains available',()=>{
  for(const route of ['/api/activate','/api/resolve']) assert.equal(isBlockedReviewRoute(route),true);
  for(const route of ['/api/authorize/ebay','/api/authorize/google','/api/verify','/api/pause','/api/dry-run']) assert.equal(isBlockedReviewRoute(route),false);
});
test('server enforces route lock, disables worker, and never defaults to original data',()=>{
  const source=fs.readFileSync(new URL('../src/server.js',import.meta.url),'utf8');
  assert.match(source,/if\(isBlockedReviewRoute\(url.pathname\)\) return send\(res,423/);
  assert.doesNotMatch(source,/setInterval|store.set\('live',true\)|store.set\('monitoring',true\)/);
  assert.match(source,/canSend:\(\)=>false/);
  assert.doesNotMatch(source,/await ebay.conversations/);
  assert.match(source,/work\/replyassist-private-new/);
  assert.doesNotMatch(source,/work\/replyassist-private'/);
});

