import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {Store} from '../src/store.js';
import {ReviewRun} from '../src/review-run.js';
import {Ebay} from '../src/ebay.js';
import {HOLDING} from '../src/config.js';
import {conversation,listing,summary,seller} from './fixtures.js';

function fixture(store=new Store(':memory:')) {
  const f={store,now:Date.now(),reads:0,listingReads:0};
  f.c=conversation('Before I buy, what is the brand?',new Date(f.now).toISOString());
  f.ebay={reviewPage:async(start,end)=>{f.range={start,end};return {summaries:[summary],truncated:false};},reviewConversation:async()=>{f.reads++;return structuredClone(f.c);},listing:async()=>{f.listingReads++;return listing();},send:()=>assert.fail('No eBay sends allowed')};
  f.runner=new ReviewRun({store,ebay:f.ebay,clock:()=>f.now});
  store.set('seller',seller);store.set('checks',{at:new Date(f.now).toISOString(),ebay:true,orders:true,listing:true,gmail:true});
  f.runner.arm();
  f.authorize=()=>store.set('messageAccess',{ok:true,at:new Date(f.now).toISOString(),seller,cutoff:store.get('reviewCutoff')});
  f.authorize();return f;
}
test('cutoff is immutable, survives reopening and excludes older messages',async()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'replyassist-test-'));
  let s=new Store(path.join(dir,'test.sqlite'));
  try {
    const f=fixture(s),cutoff=s.get('reviewCutoff');
    f.c.messages[0].receivedAt=new Date(f.now-1).toISOString();
    assert.equal((await f.runner.run()).skipped,1);assert.equal(s.proposals().length,0);
    f.now+=1000;assert.equal(f.runner.arm().cutoff,cutoff);
    s.close();s=new Store(path.join(dir,'test.sqlite'));
    assert.equal(new ReviewRun({store:s,ebay:f.ebay,clock:()=>f.now}).arm().cutoff,cutoff);
  } finally {s.close();fs.rmSync(dir,{recursive:true});}
});
test('cutoff equality is eligible, future messages are excluded and no dispatch ledger is populated',async()=>{
  const f=fixture();
  try {
    assert.equal((await f.runner.run()).processed,1);
    assert.equal(f.store.proposals().length,1);assert.equal(f.store.jobs().length,0);assert.equal(f.store.pending().length,0);
    assert.equal(f.store.get('activationAt'),null);
    f.c.messages[0].receivedAt=new Date(f.now+1).toISOString();
    assert.equal((await f.runner.run()).skipped,1);
    assert.equal(f.store.proposals()[0].replyState,'not_revalidated');
  } finally {f.store.close();}
});
test('repeated polling and changed evidence update one durable proposal, including after restart',async()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'replyassist-test-'));
  let s=new Store(path.join(dir,'test.sqlite'));
  try {
    const f=fixture(s);await f.runner.run();
    f.c.messages[0].text='Where is my order?';
    assert.equal((await f.runner.run()).duplicates,1);
    assert.equal(f.listingReads,2);assert.equal(s.proposals().length,1);
    assert.equal(s.proposals()[0].decision.kind,'post_order');
    s.close();s=new Store(path.join(dir,'test.sqlite'));
    const runner=new ReviewRun({store:s,ebay:f.ebay,clock:()=>f.now});
    assert.equal((await runner.run()).duplicates,1);assert.equal(s.proposals().length,1);
    assert.equal(s.proposals()[0].emailState,'blocked');
  } finally {s.close();fs.rmSync(dir,{recursive:true});}
});
test('staff replies retire proposals; historical holding replies suppress proposed repeats',async()=>{
  const f=fixture();
  try {
    await f.runner.run();
    f.c.messages.push({id:'staff',sender:seller,recipient:'buyer',receivedAt:new Date(f.now).toISOString(),text:'Answered',attachments:[]});
    assert.equal((await f.runner.run()).skipped,1);
    assert.equal(f.store.proposals()[0].replyState,'not_revalidated');
    f.c.messages[1].receivedAt=new Date(f.now-1000).toISOString();f.c.messages[1].text=HOLDING;
    await f.runner.run();assert.equal(f.store.proposals()[0].replyState,'would_suppress_prior_holding');
    assert.equal(f.store.proposals()[0].recoveryReviewRequired,true);
  } finally {f.store.close();}
});
test('failed full reads invalidate earlier proposals and cannot report complete',async()=>{
  const f=fixture();try {
    await f.runner.run();f.ebay.reviewConversation=async()=>{throw new Error('Incomplete history');};
    const report=await f.runner.run();assert.equal(report.failures,1);assert.equal(report.complete,false);
    assert.equal(f.store.proposals()[0].replyState,'not_revalidated');
  } finally {f.store.close();}
});
test('10-conversation cap and truncation never advance a cursor or claim full coverage',async()=>{
  const f=fixture();try {
    f.ebay.reviewPage=async()=>({summaries:Array.from({length:11},(_,i)=>({...summary,conversationId:'c'+i})),truncated:true});
    f.ebay.reviewConversation=async row=>({...f.c,id:row.conversationId});
    const report=await f.runner.run();assert.equal(report.processed,10);assert.equal(report.truncated,true);assert.equal(report.complete,false);
    assert.equal(f.store.get('dryCursor'),null);assert.equal(f.store.proposals().length,10);
  } finally {f.store.close();}
});
test('missing or stale connection/message checks stop reads; invalid cutoff fails closed',async()=>{
  const f=fixture();try {
    f.store.set('messageAccess',null);await assert.rejects(()=>f.runner.run(),/message access/);assert.equal(f.reads,0);
    f.authorize();f.now+=900001;await assert.rejects(()=>f.runner.run(),/Verify seller/);
    f.store.set('reviewCutoff','invalid');assert.throws(()=>f.runner.window(),/cutoff/);
  } finally {f.store.close();}
});
test('access check reports an empty inbox without pretending full conversation reads passed',async()=>{
  const f=fixture();try {
    f.ebay.reviewPage=async()=>({summaries:[],truncated:false});
    const check=await f.runner.checkAccess();assert.equal(check.ok,true);assert.equal(check.fullConversation,false);
    assert.equal(f.store.proposals().length,0);
  } finally {f.store.close();}
});
test('window is bounded to 24 hours and order permission alone cannot justify an automatic product answer',async()=>{
  const f=fixture();try {
    await f.runner.run();assert.equal(f.store.proposals()[0].decision.kind,'human_review');
    f.now+=2*86400000;const w=f.runner.window();assert.equal(Date.parse(w.end)-Date.parse(w.cutoff),86400000);
  } finally {f.store.close();}
});
test('connector reads full paginated conversation and rejects incomplete or excessive history',async()=>{
  const e=new Ebay({}),row=i=>({messageId:'m'+i,senderUsername:'buyer',recipientUsername:seller,messageBody:'question',createdDate:new Date().toISOString()});
  const next='https://api.ebay.com/commerce/message/v1/conversation/conversation-1?offset=50';let calls=0;
  e.json=async()=>++calls===1?{messages:[row(1)],next,total:2}:{messages:[row(2)],total:2};
  assert.equal((await e.reviewConversation(summary)).messages.length,2);
  e.json=async()=>({messages:[row(1)],total:2});await assert.rejects(()=>e.reviewConversation(summary),/Incomplete/);
  let page=0;e.json=async()=>({messages:[row(++page)],next:next+'&page='+page});
  await assert.rejects(()=>e.reviewConversation(summary),/Pagination limit/);assert.equal(page,5);
});
test('missing, stale and wrong-seller listings are visible gaps, never complete evidence',async()=>{
  const f=fixture();try {
    for(const l of [{...listing(),seller:'someone-else'},{...listing(),fetchedAt:new Date(f.now-130000).toISOString()},{...listing(),complete:false}]) {
      f.ebay.listing=async()=>l;
      const result=await f.runner.run();assert.equal(result.listingGaps,1);assert.equal(result.complete,false);
      assert.equal(f.store.proposals()[0].evidence.listing,null);assert.equal(f.store.proposals()[0].decision.kind,'human_review');
    }
  } finally {f.store.close();}
});
test('read-only summary check enforces page size, time bounds and never requests another page',async()=>{
  const e=new Ebay({});let calls=0;
  e.json=async url=>{calls++;assert.equal(new URL(url).searchParams.get('limit'),'10');return {conversations:Array.from({length:11},()=>summary),next:'ignored',total:11};};
  const a=new Date().toISOString();const p=await e.reviewPage(a,a);
  assert.equal(p.summaries.length,10);assert.equal(p.truncated,true);assert.equal(calls,1);
  await assert.rejects(()=>e.reviewPage(a,new Date(Date.parse(a)+86400001).toISOString()),/24 hours/);
});

