import test from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import fs from 'node:fs';
import vm from 'node:vm';
import {createSession} from '../src/session.js';
import {validRequest} from '../src/security.js';

async function fixture() {
  const f={session:null,csrf:'synthetic-test-csrf'};
  const server=http.createServer(async(req,res)=>{
    if(req.url==='/api/session') return f.session.bootstrap(req,res);
    if(!f.session.authenticated(req) || !validRequest(req,f.origin,f.csrf)) {res.writeHead(403);res.end(JSON.stringify({error:'Session missing'}));return;}
    res.setHeader('Content-Type','application/json');
    res.end(JSON.stringify({ok:true,csrf:f.csrf,credentials:{},dryRun:[],review:[],reviewLocked:true}));
  });
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
  f.origin='http://127.0.0.1:'+server.address().port;
  f.session=createSession(f.origin);
  f.close=()=>new Promise(resolve=>{server.close(resolve);server.closeAllConnections();});
  f.input=()=>({key:new URL(f.session.launchUrl).hash.slice(1),instanceId:f.session.instanceId});
  f.post=(input,headers={})=>fetch(f.origin+'/api/session',{method:'POST',headers:{Origin:f.origin,'Content-Type':'application/json',...headers},body:JSON.stringify(input)});
  return f;
}
test('freshly generated launch key bootstraps HttpOnly session; CSRF remains required',async()=>{
  const f=await fixture();try {
    const r=await f.post(f.input());assert.equal(r.status,200);
    const cookie=r.headers.get('set-cookie');
    assert.ok(!!cookie && cookie.includes('HttpOnly') && cookie.includes('SameSite=Strict') && cookie.includes('Path=/'),'Session cookie protections must be present');
    const jar=cookie.split(';')[0];
    assert.equal((await fetch(f.origin+'/api/status',{headers:{Cookie:jar}})).status,200);
    assert.equal((await fetch(f.origin+'/api/status')).status,403);
    assert.equal((await fetch(f.origin+'/api/protected',{method:'POST',headers:{Cookie:jar,Origin:f.origin,'Content-Type':'application/json'}})).status,403);
    assert.equal((await fetch(f.origin+'/api/protected',{method:'POST',headers:{Cookie:jar,Origin:f.origin,'Content-Type':'application/json','X-ReplyAssist-CSRF':f.csrf}})).status,200);
  } finally {await f.close();}
});
test('restart rejects old keys and cookies; malformed inputs and wrong origins fail closed',async()=>{
  const f=await fixture();try {
    const old=f.input(),oldReply=await f.post(old),cookie=oldReply.headers.get('set-cookie').split(';')[0];
    f.session=createSession(f.origin);
    assert.equal((await f.post(old)).status,403);
    assert.equal((await fetch(f.origin+'/api/status',{headers:{Cookie:cookie}})).status,403);
    for(const key of ['',null,{},'é'.repeat(64)]) assert.equal((await f.post({...f.input(),key})).status,403);
    assert.equal((await f.post(f.input(),{Origin:'https://example.invalid'})).status,403);
    const wrongHostStatus=await new Promise((resolve,reject)=>{
      const req=http.request(f.origin+'/api/session',{method:'POST',headers:{Host:'example.invalid',Origin:f.origin,'Content-Type':'application/json'}},res=>{res.resume();resolve(res.statusCode);});
      req.on('error',reject);req.end(JSON.stringify(f.input()));
    });
    assert.equal(wrongHostStatus,403);
    assert.equal((await f.post(f.input(),{'Content-Type':'text/plain'})).status,403);
    assert.equal((await f.post(f.input())).status,200);
  } finally {await f.close();}
});
test('dashboard bootstrap authenticates initial load and reused-tab hashchange after restart without revealing keys',async()=>{
  const f=await fixture();try {
    let jar='';const elements=new Map(),handlers={};
    const element=()=>({textContent:'',value:'',disabled:false,replaceChildren(){},append(){},after(){},focus(){}});
    const location={hash:'',search:''};
    const setLaunch=()=>{const u=new URL(f.session.launchUrl);location.hash=u.hash;location.search=u.search;};
    setLaunch();
    const context=vm.createContext({URL,URLSearchParams,location,history:{replaceState(){location.hash='';location.search='';}},window:{addEventListener(name,handler){handlers[name]=handler;}},document:{getElementById(id){if(!elements.has(id))elements.set(id,element());return elements.get(id);},createElement:element},fetch:async(relative,options={})=>{
      const headers={...options.headers};if(options.method==='POST')headers.Origin=f.origin;if(jar)headers.Cookie=jar;
      const r=await fetch(f.origin+relative,{...options,headers});
      const c=r.headers.get('set-cookie');if(c)jar=c.split(';')[0];return r;
    }});
    vm.runInContext(fs.readFileSync(new URL('../public/app.js',import.meta.url),'utf8'),context);
    await vm.runInContext('sessionBootstrap',context);
    assert.ok(elements.get('notice').textContent.startsWith('Authenticated review dashboard'),'Initial browser bootstrap must authenticate');
    assert.equal(location.hash,'');
    const oldLaunch=f.session.launchUrl;
    f.session=createSession(f.origin);
    const stale=new URL(oldLaunch);location.hash=stale.hash;location.search=stale.search;
    await handlers.hashchange();
    assert.ok(elements.get('notice').textContent.includes('stale or invalid'),'Stale launch must fail clearly');
    setLaunch();await handlers.hashchange();
    assert.ok(elements.get('notice').textContent.startsWith('Authenticated review dashboard'),'Reopened tab must accept the new key');
    assert.equal(location.hash,'');assert.equal(elements.get('activate').disabled,true);
  } finally {await f.close();}
});
test('launchers share one data-path resolver and Open validates current instance before opening',()=>{
  const read=name=>fs.readFileSync(new URL('../'+name,import.meta.url),'utf8');
  for(const name of ['Start-ReplyAssist-Review.ps1','Open-ReplyAssist-Review.ps1']) {
    const s=read(name);assert.ok(s.includes("'Review-Paths.ps1'"));assert.ok(s.includes('Get-ReplyAssistReviewDataPath'));
  }
  const s=read('Open-ReplyAssist-Review.ps1');
  assert.ok(s.includes('/api/instance') && s.includes('/api/session') && s.includes('server-instance.json'));
  assert.ok(s.indexOf('/api/session')<s.indexOf('Start-Process'));
});

