const $=id=>document.getElementById(id);let csrf='',state=null,view='dry';
function notice(text){$('notice').textContent=text;}
function authorizationLink(provider,url){
 const parsed=new URL(url),allowed=provider==='eBay'?['auth.ebay.com','auth2.ebay.com']:['accounts.google.com'];
 if(parsed.protocol!=='https:' || !allowed.includes(parsed.hostname))throw new Error('Unexpected authorization destination.');
 const id=provider==='eBay'?'ebaySignInLink':'googleSignInLink';
 let link=$(id);if(!link){link=document.createElement('a');link.id=id;link.className='authorization-link';link.target='_blank';link.rel='noopener noreferrer';$(provider==='eBay'?'authorizeEbay':'authorizeGoogle').after(link);}
 link.href=url;link.textContent=`Continue to ${provider} sign-in →`;link.focus();
}
async function call(path,input={}){const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-ReplyAssist-CSRF':csrf},body:JSON.stringify(input)});const d=await r.json();if(!r.ok)throw new Error(d.error || 'Request failed.');return d;}
function renderReview(){const list=view==='dry'?state.dryRun:state.review;$('review').replaceChildren();if(!list.length){$('review').textContent='No messages processed.';return;}for(const j of list){const article=document.createElement('article');for(const [tag,text] of [['h3',j.decision.kind.replaceAll('_',' ')],['small',`${j.receivedAt} · conversation ${j.conversation} · message ${j.message}`],['p',j.question],['p',`Proposed reply: ${j.decision.text}`],['p',`Reply: ${j.replyState} · Email: ${j.emailState}${j.decision.to?' → '+j.decision.to:''}`],['small',j.decision.reason]]){const el=document.createElement(tag);el.textContent=text;article.append(el);}if(view==='dry' && j.evidence){const details=document.createElement('details'),heading=document.createElement('summary'),pre=document.createElement('pre');heading.textContent='Full conversation and current listing evidence';pre.textContent=JSON.stringify(j.evidence,null,2);details.append(heading,pre);const note=document.createElement('p');note.textContent=j.note+(j.listingError?' Listing check: '+j.listingError:'');article.append(note,details);}if(view==='live'){const b=document.createElement('button');b.className='secondary';b.textContent='Mark issue resolved';b.onclick=()=>task(()=>call('resolve',{key:j.key}),'Issue marked resolved.');article.append(b);}$('review').append(article);}}
async function refresh(){const r=await fetch('/api/status');const d=await r.json();if(!r.ok)throw new Error(d.error);state=d;csrf=d.csrf;$('mode').textContent=d.live?'Automatic replies enabled':'Sending disabled';$('gmailState').textContent=d.checks?.gmail?'Mailbox verified for background use':d.credentials.gmail?'Authorized · verification needed':'Background authorization pending';$('ebayState').textContent=d.seller?`Seller: ${d.seller}`:d.credentials.ebaySeller?'Seller token stored · verification needed':d.credentials.ebayClient?'test 2 credential stored · seller authorization pending':'Seller not yet connected.';$('connectionState').textContent=d.checks?.ok?'Seller, order, listing and Gmail checks passed':'Connection checks pending';$('checks').textContent=JSON.stringify(d.checks || {},null,2);$('testState').textContent=d.tests?.ok?'Offline tests passed':'Tests pending';$('testOutput').textContent=d.tests?.output || 'No tests run yet.';$('pollState').textContent=d.lastPoll?JSON.stringify(d.lastPoll):'Monitoring is stopped.';$('dryRun').disabled=!(d.messageAccess?.ok && d.reviewCutoff && d.tests?.version==='read-only-v2' && d.tests?.ok);$('mode').textContent='Read-only review: customer replies and emails hard-blocked';$('cutoffState').textContent=d.reviewCutoff ? 'Immutable processing cutoff: '+d.reviewCutoff : 'No processing cutoff established.';$('messageChecks').textContent=JSON.stringify(d.messageAccess || {},null,2);$('runReport').textContent=JSON.stringify(d.reviewRun || {},null,2);$('activate').disabled=d.reviewLocked || !(d.tests?.ok && d.checks?.ok && d.lastPoll?.mode==='dry_run' && !d.lastPoll?.failures && d.lastPoll?.orderLookupOk);renderReview();}
async function task(fn,success){try{notice('Working…');const result=await fn();await refresh();notice(success || 'Completed.');return result;}catch(e){notice(e.message);}}
$('ebayCredentials').onsubmit=e=>{e.preventDefault();const secret=$('ebaySecret').value;$('ebaySecret').value='';task(()=>call('credentials/ebay',{clientId:$('clientId').value,secret}),'test 2 credential encrypted and saved.');};
$('googleCredentials').onsubmit=e=>{e.preventDefault();task(async()=>{const file=$('googleFile').files[0];if(!file)throw new Error('Select a Desktop OAuth client JSON file.');const client=JSON.parse(await file.text());$('googleFile').value='';return call('credentials/google',{client});},'Google client encrypted and saved.');};
$('authorizeEbay').onclick=()=>task(async()=>{const d=await call('authorize/ebay',{runame:$('runame').value.trim()});authorizationLink('eBay',d.url);},'Click “Continue to eBay sign-in” below the authorization button. Sign in to your seller account and approve test 2 access.');
$('ebayComplete').onsubmit=e=>{e.preventDefault();const callback=$('callback').value;$('callback').value='';task(()=>call('authorize/ebay/complete',{callback}),'Seller authorization stored securely. Run the connection checks.');};
