$('refresh').onclick=()=>task(refresh,'Status refreshed.');
$('showDry').onclick=()=>{view='dry';renderReview();};$('showLive').onclick=()=>{view='live';renderReview();};
let sessionBootstrap=Promise.resolve();
function bootstrapSession() {
 const key=location.hash.slice(1),instanceId=new URLSearchParams(location.search).get('instance');
 history.replaceState(null,'','/');
 sessionBootstrap=sessionBootstrap.then(async()=>{
  try {
   if(key) {
    const response=await fetch('/api/session',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({key,instanceId})});
    const result=await response.json();
    if(!response.ok || !result.ok) throw new Error(result.error || 'Session bootstrap failed. Run Open-ReplyAssist-Review.ps1 again.');
   }
   await refresh();
   notice('Authenticated review dashboard. Customer replies and emails remain hard-blocked. Existing credentials are preserved.');
  } catch(e) {notice(e.message);}
 });
 return sessionBootstrap;
}
window.addEventListener('hashchange',bootstrapSession);
window.addEventListener('pageshow',event=>{if(event.persisted)bootstrapSession();});
bootstrapSession();

