# Shared pinned path for Start/Open; never fall back to the original private folder.
function Get-ReplyAssistReviewDataPath {
    $expected = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..\work\replyassist-private-new'))
    if ($env:REPLYASSIST_DATA_DIR -and [IO.Path]::GetFullPath($env:REPLYASSIST_DATA_DIR) -ne $expected) {
        throw 'REPLYASSIST_DATA_DIR points to another location. Clear that variable in this normal-user PowerShell window; no data was changed.'
    }
    return $expected
}

