$ErrorActionPreference = 'Stop'
$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
if ($identity.Name -match 'CodexSandbox' -or $env:USERPROFILE -ne 'C:\Users\ANANGSHA HALDER') { throw 'Use your normal Windows account.' }
. (Join-Path $PSScriptRoot 'Review-Paths.ps1')
$privatePath = Get-ReplyAssistReviewDataPath
$env:REPLYASSIST_DATA_DIR = $privatePath
$setup = Get-Content -LiteralPath (Join-Path $privatePath 'review-setup.json') -Raw | ConvertFrom-Json
if ($setup.ownerSid -ne $identity.User.Value -or $setup.build -ne 'replyassist-review') { throw 'Review setup ownership mismatch.' }
$metadataPath = Join-Path $privatePath 'server-instance.json'
if (!(Test-Path -LiteralPath $metadataPath)) { throw 'Restart the review server with the updated launcher; current-instance metadata is missing.' }
$metadata = Get-Content -LiteralPath $metadataPath -Raw | ConvertFrom-Json
if ($metadata.build -ne 'replyassist-review' -or $metadata.dataDir -ne $privatePath -or $metadata.instanceId -notmatch '^[a-f0-9]{32}$') { throw 'Review launch metadata does not match this setup.' }
$launchUrl = (Get-Content -LiteralPath (Join-Path $privatePath 'launch-url.txt') -Raw).Trim()
if ($launchUrl -notmatch '^http://127\.0\.0\.1:43127/\?instance=([a-f0-9]{32})#([a-f0-9]{64})$') { throw 'Restart the review server to replace its stale launch file.' }
$instanceFromUrl = $Matches[1]
$launchKey = $Matches[2]
if ($instanceFromUrl -ne $metadata.instanceId) { throw 'Launch file and server metadata differ. Restart the review server.' }
# No output from these requests: keys/cookies are never printed or placed in query strings.
try {
    $live = Invoke-RestMethod -Uri 'http://127.0.0.1:43127/api/instance' -Method Get -TimeoutSec 5
    if ($live.build -ne $metadata.build -or $live.instanceId -ne $metadata.instanceId -or $live.pid -ne $metadata.pid) { throw 'Instance mismatch' }
    $payload = @{key=$launchKey;instanceId=$metadata.instanceId} | ConvertTo-Json -Compress
    $verified = Invoke-RestMethod -Uri 'http://127.0.0.1:43127/api/session' -Method Post -Headers @{Origin='http://127.0.0.1:43127'} -ContentType 'application/json' -Body $payload -TimeoutSec 5
    if (!$verified.ok -or $verified.instanceId -ne $metadata.instanceId) { throw 'Session bootstrap failed' }
} catch {
    throw 'Current-server session verification failed. Stop the old review server and restart using Start-ReplyAssist-Review.ps1. No browser launch was attempted.'
} finally {
    $launchKey = $null
    $payload = $null
    $Matches = $null
}
# Non-secret nonce forces a document navigation even if the browser reuses a tab.
$openUrl = $launchUrl.Replace('#',('&open='+[Guid]::NewGuid().ToString('N')+'#'))
try { Start-Process -FilePath $openUrl -ErrorAction Stop | Out-Null }
catch { throw 'Verified the current session, but Windows could not open the browser. Run this Open script again.' }
finally { $openUrl=$null; $launchUrl=$null }
Write-Output 'Current server and launch key verified; authenticated dashboard opened.'

Start-ReplyAssist-Review.ps1:
param([switch]$OpenDashboard)
$ErrorActionPreference = 'Stop'
$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
$sid = $identity.User.Value
if ($identity.Name -match 'CodexSandbox' -or $sid -eq 'S-1-5-18' -or $env:USERPROFILE -ne 'C:\Users\ANANGSHA HALDER') {
    throw 'Run this script from PowerShell opened under your normal Windows account (C:\Users\ANANGSHA HALDER), not Codex or SYSTEM.'
}
$root = $PSScriptRoot
. (Join-Path $root 'Review-Paths.ps1')
$privatePath = Get-ReplyAssistReviewDataPath
$node = (Get-Command node.exe -ErrorAction Stop).Source
$nodeVersion = & $node --version
if ($LASTEXITCODE -ne 0 -or [version]$nodeVersion.TrimStart('v') -lt [version]'22.13.0') { throw 'Node.js 22.13 or newer is required.' }
# Never attach a new session to an existing service, including the original build.
$probe = New-Object Net.Sockets.TcpClient
try {
    $probe.Connect('127.0.0.1',43127)
    throw 'Port 43127 is already occupied. Stop the existing instance yourself before launching the review build.'
} catch [Net.Sockets.SocketException] {
    if ($_.Exception.SocketErrorCode -ne [Net.Sockets.SocketError]::ConnectionRefused) { throw }
} finally { $probe.Dispose() }
# Refuse links anywhere along the target path.
$walk = $privatePath
while ($walk) {
    if (Test-Path -LiteralPath $walk) {
        if ((Get-Item -LiteralPath $walk -Force).Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'Private-data path must not contain links.' }
    }
    $parent = Split-Path -Path $walk -Parent
    if ($parent -eq $walk) { break }
    $walk = $parent
}
$env:REPLYASSIST_NORMAL_USER_SID = $sid
$env:REPLYASSIST_DATA_DIR = $privatePath
$env:REPLYASSIST_OPEN_DASHBOARD = if ($OpenDashboard) { '1' } else { '0' }
if (Test-Path -LiteralPath $privatePath) {
    $marker = Join-Path $privatePath 'review-setup.json'
    if (!(Test-Path -LiteralPath $marker)) { throw 'Target already exists without a completed fresh setup. Nothing was changed; preserve it for inspection.' }
    $setup = Get-Content -LiteralPath $marker -Raw | ConvertFrom-Json
    if ($setup.version -ne 1 -or $setup.ownerSid -ne $sid -or $setup.build -ne 'replyassist-review') { throw 'Setup ownership or build mismatch.' }
    if (!(Test-Path -LiteralPath (Join-Path $privatePath 'review.sqlite'))) { throw 'Initialized database is missing; refusing to silently replace it.' }
} else {
    & $node (Join-Path $root 'src\init-review.js')
    if ($LASTEXITCODE -ne 0) { throw 'Initialization failed. Any partial new directory is preserved; do not copy credentials into it.' }
}
# Validate owner and exact inherited ACL on every file before starting the server.
$items = @((Get-Item -LiteralPath $privatePath -Force)) + @(Get-ChildItem -LiteralPath $privatePath -Force -Recurse)
foreach ($item in $items) {
    if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'Private data contains a link.' }
    $acl = Get-Acl -LiteralPath $item.FullName
    if ($acl.GetOwner([Security.Principal.SecurityIdentifier]).Value -ne $sid) { throw 'Private data has another owner.' }
    $rules = @($acl.GetAccessRules($true,$true,[Security.Principal.SecurityIdentifier]))
    if ($rules.Count -ne 2) { throw 'Private data ACL is not restricted to your account and SYSTEM.' }
    foreach ($allowed in @($sid,'S-1-5-18')) {
        $matches = @($rules | Where-Object { $_.IdentityReference.Value -eq $allowed -and $_.AccessControlType -eq 'Allow' -and $_.FileSystemRights -eq 'FullControl' })
        if ($matches.Count -ne 1) { throw 'Unexpected private-data access rule.' }
    }
}
# Foreground server deliberately keeps lifecycle visible. No scheduled task is installed.
Write-Output 'Starting locked review dashboard. Keep this window open; Ctrl+C stops it.'
Write-Output 'In a second normal-user PowerShell window, run Open-ReplyAssist-Review.ps1 from this build directory.'
Push-Location $root
try { & $node 'src\server.js' } finally {
    Pop-Location
    Remove-Item Env:\REPLYASSIST_NORMAL_USER_SID -ErrorAction SilentlyContinue
    Remove-Item Env:\REPLYASSIST_DATA_DIR -ErrorAction SilentlyContinue
    Remove-Item Env:\REPLYASSIST_OPEN_DASHBOARD -ErrorAction SilentlyContinue
}

