import {randomBytes} from 'node:crypto';
import {ReviewRun} from '../src/review-run.js';
import {fingerprint,latestCustomer} from '../src/policy.js';
import {HOLDING,CLIENT_ID} from '../src/config.js';
import {request} from '../src/http.js';

const TTL=15*60000;
export class ManualReviewError extends Error {}
const fail=message=>{throw new ManualReviewError(message);};
const fresh=(at,now)=>Number.isFinite(Date.parse(at))&&now-Date.parse(at)>=0&&now-Date.parse(at)<=TTL;
const normalize=text=>text.trim().replace(/\s+/g,' ').toLowerCase();
function checks(ctx,ebay,now){new ReviewRun({store:ctx.store,ebay,clock:()=>now}).requireChecks();if(ctx.store.get('seller')?.toLowerCase()!=='virventures')fail('Verify the VirVentures seller again.');}
function validate(c,seller){
 if(!c?.complete||c.type!=='FROM_MEMBERS'||!c.messages?.length||c.messages.some(m=>!m.id||!m.sender||!m.recipient||!Number.isFinite(Date.parse(m.receivedAt))))fail('Complete conversation evidence is required.');
 const m=latestCustomer(c,seller);if(!m)fail('This conversation has already been answered or has no eligible customer message.');
 if(c.messages.some(x=>![x.sender.toLowerCase(),x.recipient.toLowerCase()].includes(seller)||![seller,m.sender.toLowerCase()].includes(x.sender.toLowerCase())||![seller,m.sender.toLowerCase()].includes(x.recipient.toLowerCase())))fail('Conversation participants could not be verified.');
 return m;
}
export async function loadOlder(input,ctx,ebay,sessionId,now=Date.now()){
 checks(ctx,ebay,now);const start=Date.parse(input.start),end=Math.min(start+86400000,now);
 if(!Number.isFinite(start)||start>now||start<now-30*86400000)fail('Choose a starting time within the last 30 days. Each search covers at most 24 hours.');
 const page=await ebay.reviewPage(new Date(start).toISOString(),new Date(end).toISOString(),AbortSignal.timeout(120000));
 const inbox={at:new Date(now).toISOString(),sessionId,start:new Date(start).toISOString(),end:new Date(end).toISOString(),...page};
 ctx.store.set('manualInbox',inbox);return {ok:true,count:page.summaries.length,truncated:page.truncated};
}
export async function prepareOlder(input,ctx,ebay,sessionId,now=Date.now()){
 checks(ctx,ebay,now);const inbox=ctx.store.get('manualInbox');
 if(!inbox||inbox.sessionId!==sessionId||!fresh(inbox.at,now))fail('Load older conversations again before selecting one.');
 const summary=inbox.summaries.find(s=>s.conversationId===input.conversationId);
 if(!summary)fail('Select a conversation from the loaded results.');
 const c=await ebay.reviewConversation(summary,AbortSignal.timeout(120000));
 if(c.id!==summary.conversationId)fail('Conversation identity mismatch.');
 const seller='virventures',m=validate(c,seller),cutoff=ctx.store.get('reviewCutoff');
 if(!cutoff||!(Date.parse(m.receivedAt)<Date.parse(cutoff)))fail('This section is only for customer messages before the existing cutoff.');
 const key=JSON.stringify([seller,c.id,m.id]);
 if(ctx.store.job(key))fail('A send attempt already exists for this message. Review its status; do not retry.');
 let listing=null,listingNote='No listing reference was returned. Only the holding response can be sent.';
 if(c.itemId){try{listing=await ebay.listing(c.itemId);if(!listing.complete||listing.itemId!==c.itemId||listing.seller?.toLowerCase()!==seller)throw new Error();listingNote='Review the full listing and conversation. Earlier staff replies are not proof of product specifications.';}catch{listing=null;listingNote='Listing evidence could not be verified. Only the holding response can be sent.';}}
 const draft={id:randomBytes(24).toString('hex'),sessionId,key,summary,seller,customer:m.sender,message:m.id,conversation:c.id,hash:fingerprint(c),createdAt:new Date(now).toISOString(),expiresAt:new Date(now+TTL).toISOString(),text:HOLDING,listingNote,evidence:{conversation:c,listing}};
 const drafts=ctx.store.get('manualDrafts',[]).filter(d=>fresh(d.createdAt,now)&&d.sessionId!==sessionId);drafts.push(draft);ctx.store.set('manualDrafts',drafts);return {ok:true,draftId:draft.id};
}
// Reservation is committed by the caller BEFORE any network send. Never clear it
// automatically: a crash, timeout, or failed final commit must not cause a retry.
export async function reserveOlder(input,ctx,ebay,sessionId,now=Date.now()){
 checks(ctx,ebay,now);
 const d=ctx.store.get('manualDrafts',[]).find(x=>x.id===input.draftId&&x.sessionId===sessionId);
 if(!d||!fresh(d.createdAt,now))fail('Review expired. Load and review this conversation again.');
 if(input.approved!==true)fail('Explicit approval of the displayed reply is required.');
 const text=typeof input.text==='string'?input.text.trim():'';
 if(!text||text.length>2000)fail('Enter a reply between 1 and 2,000 characters.');
 if(text!==HOLDING&&(!d.evidence.listing||input.factsChecked!==true))fail('Verify the listing facts or use the holding response.');
 if(ctx.store.job(d.key))fail('A send attempt already exists. It will not be repeated.');
 const c=await ebay.reviewConversation(d.summary,AbortSignal.timeout(120000)),m=validate(c,d.seller);
 if(c.id!==d.conversation||m.id!==d.message||fingerprint(c)!==d.hash)fail('The conversation changed. Review it again before sending.');
 if(c.messages.some(x=>x.sender.toLowerCase()===d.seller&&normalize(x.text)===normalize(text)))fail('This reply has already been sent in this conversation.');
 if(text!==HOLDING){const listing=await ebay.listing(c.itemId);const previous=d.evidence.listing;const facts=l=>JSON.stringify([l.itemId,l.seller,l.title,l.description,l.specifics,l.active,l.multiVariation,l.complete]);if(!listing.complete||facts(listing)!==facts(previous))fail('Listing evidence changed. Review it again.');}
 const job={key:d.key,seller:d.seller,conversation:d.conversation,message:d.message,replyState:'reserved',emailState:'blocked',manual:true,text,sessionId,created:new Date(now).toISOString()};
 if(!ctx.store.insert(job))fail('A send attempt already exists.');
 return {draft:d,job};
}
export async function transmitOlder(ebay,reservation){
 const {draft:d,job}=reservation;
 if(await ebay.identity()!==d.seller)fail('Seller identity changed. No reply was sent.');
 const c=await ebay.reviewConversation(d.summary,AbortSignal.timeout(120000)),m=validate(c,d.seller);
 if(c.id!==d.conversation||m.id!==d.message||fingerprint(c)!==d.hash)fail('Conversation changed after approval. No reply was sent.');
 return sendApproved(ebay,job);
}
async function sendApproved(ebay,job){
 if(ebay.vault.load().ebayClientId!==CLIENT_ID)fail('Only test 2 credentials are permitted.');
 const token=await ebay.token();
 const result=await request('https://api.ebay.com/commerce/message/v1/send_message',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({conversationId:job.conversation,messageText:job.text,emailCopyToSender:false})});
 if(!result.messageId)throw new Error('Uncertain send result.');return result.messageId;
}
export async function sendOlder(input,cfg,sessionId,{transaction,makeEbay}){
 const reservation=await transaction(cfg,ctx=>reserveOlder(input,ctx,makeEbay(ctx.vault),sessionId));
 let messageId;
 try{
  // Obtain credentials independently after the durable reservation commits.
  const vault=await transaction(cfg,ctx=>({load:()=>ctx.vault.load()}),{readOnly:true});
  messageId=await transmitOlder(makeEbay(vault),reservation);
 }catch(error){
  const status=error instanceof ManualReviewError?'blocked':'unknown';
  await transaction(cfg,ctx=>{const j=ctx.store.job(reservation.job.key);j.replyState=status;ctx.store.save(j);});
  fail(status==='blocked'?error.message:'Send outcome is uncertain. Check eBay Sent messages. Automatic retry is blocked.');
 }
 await transaction(cfg,ctx=>{const j=ctx.store.job(reservation.job.key);j.replyState='sent';j.sentMessageId=messageId;j.sentAt=new Date().toISOString();ctx.store.save(j);ctx.store.log('manual_reply_sent',{conversation:j.conversation,message:j.message,sentMessageId:messageId});});
 return {ok:true,sent:true,messageId};
}

test/manual-review.test.js:
import test from 'node:test';
import assert from 'node:assert/strict';
import {Store} from '../src/store.js';
import {loadOlder,prepareOlder,reserveOlder,sendOlder} from '../cloud/manual-review.js';
import {HOLDING,CLIENT_ID} from '../src/config.js';
const now=Date.now(),stamp=offset=>new Date(now+offset).toISOString();
function fixture(){
 const store=new Store(':memory:');store.set('seller','virventures');store.set('checks',{at:stamp(0),ebay:true,orders:true,listing:true,gmail:true});store.set('reviewCutoff',stamp(-1000));
 const summary={conversationId:'conversation',conversationType:'FROM_MEMBERS',referenceType:'LISTING',referenceId:'123'};
 const c={id:'conversation',itemId:'123',type:'FROM_MEMBERS',complete:true,messages:[{id:'old',sender:'virventures',recipient:'buyer',text:'Earlier staff answer',receivedAt:stamp(-20000),attachments:[]},{id:'new',sender:'buyer',recipient:'virventures',text:'Please confirm the size again',receivedAt:stamp(-10000),attachments:[]}]};
 const listing={itemId:'123',seller:'virventures',title:'Scissors',description:'Size unconfirmed',specifics:[],active:true,complete:true,fetchedAt:stamp(0)};
 const vault={load:()=>({ebayClientId:CLIENT_ID})};
 const ebay={vault,identity:async()=> 'virventures',token:async()=> 'fake',reviewPage:async()=>({summaries:[summary],truncated:false}),reviewConversation:async()=>structuredClone(c),listing:async()=>structuredClone(listing)};
 return {ctx:{store,vault},ebay,c,listing,summary};
}
async function ready(f){await loadOlder({start:stamp(-86400000)},f.ctx,f.ebay,'s',now);await prepareOlder({conversationId:'conversation'},f.ctx,f.ebay,'s',now);return {draftId:f.ctx.store.get('manualDrafts')[0].id,text:HOLDING,approved:true};}
test('older follow-up after staff reply is reviewable without changing cutoff',async()=>{const f=fixture();try{const cutoff=f.ctx.store.get('reviewCutoff');await ready(f);assert.equal(f.ctx.store.get('reviewCutoff'),cutoff);const d=f.ctx.store.get('manualDrafts')[0];assert.equal(d.message,'new');assert.equal(d.text,HOLDING);assert.equal(d.customer,'buyer');assert.equal(d.evidence.conversation.messages.length,2);}finally{f.ctx.store.close();}});
test('reject invalid window, unlisted selection and another session',async()=>{const f=fixture();try{await assert.rejects(loadOlder({start:'bad'},f.ctx,f.ebay,'s',now));await ready(f);await assert.rejects(prepareOlder({conversationId:'foreign'},f.ctx,f.ebay,'s',now));await assert.rejects(prepareOlder({conversationId:'conversation'},f.ctx,f.ebay,'other',now));}finally{f.ctx.store.close();}});
test('newer customer messages and already staff answered messages are excluded',async()=>{const f=fixture();try{await ready(f);f.c.messages.at(-1).receivedAt=stamp(0);await assert.rejects(prepareOlder({conversationId:'conversation'},f.ctx,f.ebay,'s',now),/before/);f.c.messages.push({id:'staff',sender:'virventures',recipient:'buyer',text:'Answered',receivedAt:stamp(1)});await assert.rejects(prepareOlder({conversationId:'conversation'},f.ctx,f.ebay,'s',now),/answered/);}finally{f.ctx.store.close();}});
test('approval, session, stale review, changed thread and duplicate holding fail closed',async()=>{const f=fixture();try{const input=await ready(f);await assert.rejects(reserveOlder({...input,approved:false},f.ctx,f.ebay,'s',now),/approval/);await assert.rejects(reserveOlder(input,f.ctx,f.ebay,'other',now),/expired/);await assert.rejects(reserveOlder(input,f.ctx,f.ebay,'s',now+16*60000));f.c.messages[0].text='changed';await assert.rejects(reserveOlder(input,f.ctx,f.ebay,'s',now),/changed/);f.c.messages[0].text=HOLDING;const input2=await ready(f);await assert.rejects(reserveOlder(input2,f.ctx,f.ebay,'s',now),/already been sent/);assert.equal(f.ctx.store.jobs().length,0);}finally{f.ctx.store.close();}});
test('custom facts require listing and attestation and fresh unchanged listing',async()=>{const f=fixture();try{const input=await ready(f);await assert.rejects(reserveOlder({...input,text:'Custom answer'},f.ctx,f.ebay,'s',now),/Verify/);f.listing.description='Changed';await assert.rejects(reserveOlder({...input,text:'Custom answer',factsChecked:true},f.ctx,f.ebay,'s',now),/Listing evidence changed/);}finally{f.ctx.store.close();}});
test('durable reservation prevents repeat after state round trip or crash',async()=>{const f=fixture();try{const input=await ready(f);await reserveOlder(input,f.ctx,f.ebay,'s',now);assert.equal(f.ctx.store.jobs()[0].replyState,'reserved');await assert.rejects(reserveOlder(input,f.ctx,f.ebay,'s',now),/attempt/);await assert.rejects(prepareOlder({conversationId:'conversation'},f.ctx,f.ebay,'s',now),/attempt/);}finally{f.ctx.store.close();}});
test('successful approved send commits reservation first; no replay, no email',async()=>{const f=fixture();const original=globalThis.fetch;try{const input=await ready(f);let sends=0;globalThis.fetch=async(url,opts)=>{assert.equal(f.ctx.store.jobs()[0].replyState,'reserved');assert.equal(url,'https://api.ebay.com/commerce/message/v1/send_message');assert.equal(JSON.parse(opts.body).messageText,HOLDING);sends++;return new Response(JSON.stringify({messageId:'sent-id'}));};const deps={transaction:async(cfg,fn)=>fn(f.ctx),makeEbay:()=>f.ebay};const out=await sendOlder(input,{},'s',deps);assert.equal(out.sent,true);assert.equal(f.ctx.store.jobs()[0].replyState,'sent');assert.equal(f.ctx.store.jobs()[0].emailState,'blocked');await assert.rejects(sendOlder(input,{},'s',deps));assert.equal(sends,1);}finally{globalThis.fetch=original;f.ctx.store.close();}});
test('ambiguous network failure remains unknown and cannot resend',async()=>{const f=fixture();const original=globalThis.fetch;try{const input=await ready(f);let sends=0;globalThis.fetch=async()=>{sends++;throw new Error('timeout after possible send');};const deps={transaction:async(cfg,fn)=>fn(f.ctx),makeEbay:()=>f.ebay};await assert.rejects(sendOlder(input,{},'s',deps),/uncertain/);assert.equal(f.ctx.store.jobs()[0].replyState,'unknown');await assert.rejects(sendOlder(input,{},'s',deps));assert.equal(sends,1);}finally{globalThis.fetch=original;f.ctx.store.close();}});
test('staff reply between reservation and transmission blocks sending',async()=>{const f=fixture();try{const input=await ready(f);let tx=0;const deps={transaction:async(cfg,fn)=>{tx++;if(tx===2)f.c.messages.push({id:'staff',sender:'virventures',recipient:'buyer',text:'Already answered',receivedAt:stamp(0)});return fn(f.ctx);},makeEbay:()=>f.ebay};await assert.rejects(sendOlder(input,{},'s',deps),/answered/);assert.equal(f.ctx.store.jobs()[0].replyState,'blocked');}finally{f.ctx.store.close();}});
